insert into typenews_content_quality_0047 (id, language, mode, old_text, new_text)
values
    (555, 'kor', 'long', '오랜 약속을 마치고 멀리 켜진 불빛은 서두르던 걸음을 잠시 멈추게 한다. 차를 한 잔 마시며 멀리 켜진 불빛은 작은 용기를 다시 꺼내 들게 한다. 불을 낮춘 다음 멀리 켜진 불빛은 평범한 순간의 소중함을 다시 알려 준다.', '완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.'),
    (556, 'kor', 'long', '끝이라고 믿었던 장면에서, 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어, 그리고 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.'),
    (917, 'eng', 'short', 'When the whole city becomes quiet, a closed door is not the end because we can still choose another road.', 'Soft morning light brings a little warmth to a tired heart.'),
    (927, 'eng', 'short', 'On a day meant for starting again, a new language becomes familiar through useful phrases before perfect sentences.', 'The sound of summer rain makes an ordinary day feel quietly special.'),
    (929, 'eng', 'short', 'After the rain has passed, being a beginner means there is still plenty of room to grow.', 'A familiar song returns a forgotten memory with gentle clarity.'),
    (933, 'eng', 'short', 'Before beginning unfamiliar work, a complex problem becomes easier when facts and guesses are separated.', 'The quiet evening breeze gives crowded thoughts a place to rest.'),
    (938, 'eng', 'short', 'When old friends meet again, asking how another person feels matters most when you wait patiently for the answer.', 'A handwritten note turns a brief pause into a lasting memory.'),
    (952, 'eng', 'short', 'After a small success, a precise question can solve a blocked task faster than silent effort.', 'The first winter snow reminds us that comfort can be simple.'),
    (956, 'eng', 'short', 'When no answer can be certain, do not trust the words final chance because we can still write another scene.', 'Warm light by the window leaves a soft trace long after it fades.'),
    (966, 'eng', 'short', 'On a night meant for sleeping early, after three alarms, even a sleepy person becomes serious near fresh coffee.', 'A slow walk home makes the familiar world feel new again.'),
    (972, 'eng', 'short', 'When time begins to feel scarce, finding one improvement makes an ordinary day worth remembering.', 'The scent of fresh coffee invites the heart to move at a kinder pace.'),
    (973, 'eng', 'short', 'When a mistake remains on your mind, a complex problem becomes easier when facts and guesses are separated.', 'A clear sky after rain holds more meaning than words can explain.'),
    (976, 'eng', 'short', 'When gratitude needs a voice, a real apology includes a different action instead of a longer explanation.', 'The moon above the rooftops carries hope into the quieter parts of the day.'),
    (984, 'eng', 'short', 'While walking along a different road, check difficult work in small stages before errors become expensive.', 'A small act of kindness makes room for a small and honest smile.'),
    (986, 'eng', 'short', 'When escape becomes possible, do not trust the words final chance because we can still write another scene.', 'The final page of a book helps a restless mind become still.'),
    (998, 'eng', 'short', 'When a snack becomes strangely persuasive, the promise to sleep early grows more philosophical as midnight approaches.', 'A peaceful weekend morning brings distant feelings a little closer.'),
    (999, 'eng', 'short', 'As a deadline moves closer, comparing your work with yesterday is usually more useful than comparing it with others.', 'The glow of sunset offers the courage to begin once more.'),
    (1000, 'eng', 'short', 'While walking along a different road, being a beginner means there is still plenty of room to grow.', 'A flower beside the road turns solitude into a peaceful kind of company.'),
    (1005, 'eng', 'short', 'As a deadline moves closer, finishing a quick task now can remove hours of unnecessary worry.', 'The hush of an empty room reminds us to notice what usually passes by.'),
    (1009, 'eng', 'short', 'When gratitude needs a voice, the warmth of a conversation depends on how carefully each person listens.', 'A long awaited message settles gently into the heart.'),
    (1012, 'eng', 'short', 'When an accepted fact is questioned again, an octopus has three hearts, and two of them move blood through the gills.', 'The rhythm of distant waves makes tomorrow feel a little less uncertain.'),
    (1014, 'eng', 'short', 'On a day meant for starting again, a useful meeting ends with clear actions instead of impressive speeches.', 'A gentle voice keeps a tender moment from disappearing.'),
    (1018, 'eng', 'short', 'Before an important choice, if we run now the scene will stop, but one more step can change the story.', 'An old photograph shows that healing often arrives without noise.'),
    (1024, 'eng', 'short', 'While searching for one missing object, cleaning a drawer reveals missing objects and forgotten plans in equal numbers.', 'The first green leaf gives the present moment a softer shape.'),
    (1025, 'eng', 'short', 'When time begins to feel scarce, a new language becomes familiar through useful phrases before perfect sentences.', 'A quiet moment alone brings calm to the end of a busy day.'),
    (1027, 'eng', 'long', 'After the final note, the color left in the sky brings distant feelings a little closer. The light across the river gives crowded thoughts a place to rest. When the clouds begin to clear, the warmth beside an empty chair reminds us to notice what usually passes by.', 'A small action today can travel farther than a perfect plan tomorrow. Lasting change usually begins with an action small enough to repeat. Moving slowly is still progress when the direction remains clear.'),
    (1031, 'eng', 'long', 'When the whole city becomes quiet, when the whole city became quiet, your voice was the one sound I could find. Letting go would be easier, but I did not come here for an easy ending.', 'When the list feels endless, complete the smallest useful task first. A complicated day becomes clearer when vague pressure turns into specific actions. Important decisions are often clearer in the morning than late at night.'),
    (1043, 'eng', 'long', 'While standing in front of the refrigerator, new exercise clothes can look surprisingly athletic before any exercise begins. At the same time, opening the refrigerator without a plan still counts as a short expedition.', 'A useful meeting ends with clear actions instead of impressive speeches. Clear standards and visible next steps allow a team to move without needless confusion. Priority should follow real impact rather than the loudest request.'),
    (1046, 'eng', 'long', 'While walking along a different road, a new language becomes familiar through useful phrases before perfect sentences. At the same time, short sessions repeated over time often build stronger memories than one long session.', 'After three alarms, even a sleepy person becomes serious near fresh coffee. Ordinary plans often become memorable because they fail in harmless and amusing ways. Opening the refrigerator without a plan still counts as a short expedition.'),
    (1048, 'eng', 'long', 'When the familiar method fails, rest can be a wise part of progress rather than a sign of surrender. Being a beginner means there is still plenty of room to grow.', 'A closed door is not the end because we can still choose another road. A character often discovers what matters most when every easy path disappears. If we run now the scene will stop, but one more step can change the story.'),
    (1049, 'eng', 'long', 'While taking a brief pause, when a conversation stalls, confirm what the other person meant, and important decisions are often clearer in the morning than late at night.', 'The starlight we see tonight began its journey far back in cosmic history. Different natural events become more meaningful when we examine the connections between them. An octopus has three hearts, and two of them move blood through the gills.'),
    (1053, 'eng', 'long', 'When gratitude needs a voice, an old friendship remembers the path back even after a long time apart. Different opinions can begin a deeper understanding rather than end a friendship.', 'Learning begins faster when you can describe exactly what you do not know. Learning is less about collecting facts than about finding and repairing gaps in understanding. Short sessions repeated over time often build stronger memories than one long session.'),
    (1055, 'eng', 'long', 'A large cloud can contain an enormous amount of water despite its gentle shape, and bees use the direction and speed of a dance to describe a food source.', 'Gratitude should be spoken aloud even in the relationships that feel most familiar. Relationships are sustained by regular attention and the patience to listen accurately. Asking how another person feels matters most when you wait patiently for the answer.'),
    (1057, 'eng', 'long', 'On the slow journey home, check difficult work in small stages before errors become expensive. At the same time, repeated mistakes often reveal a weak process rather than a careless person.', 'Evening sunlight crossed the room and rested softly on the books beside the window. An ordinary view can quietly change the pace of the mind. When the mind feels crowded, it helps to observe each feeling before searching for an answer. For once, I decided to stop rushing and let the day move at the pace of my own heart.'),
    (1058, 'eng', 'long', 'Near the end of day, the light from distant lamps turns a brief pause into a lasting memory. After the final note, the warmth beside an empty chair shows that healing often arrives without noise. While turning a page, the letter in the mailbox makes the familiar world feel new again.', 'Moving slowly is still progress when the direction remains clear. Progress depends less on speed than on keeping a useful direction. A person is shaped less by failure than by the decision to try again.'),
    (1060, 'eng', 'long', 'Do not trust the words final chance because we can still write another scene. When no answer can be certain, we did not lose time as much as we lost the courage to speak honestly.', 'Important decisions are often clearer in the morning than late at night. A useful routine depends more on a repeatable structure than on perfect discipline. Write down an important thought before asking memory to protect it.'),
    (1061, 'eng', 'long', 'After making a new exercise plan, cleaning a drawer reveals missing objects and forgotten plans in equal numbers. At the same time, after three alarms, even a sleepy person becomes serious near fresh coffee.', 'Priority should follow real impact rather than the loudest request. Reliable collaboration depends on sharing judgment as openly as the final result. A precise question can solve a blocked task faster than silent effort.'),
    (1066, 'eng', 'long', 'Careful readers mark both the important lines and the parts they do not understand, and people who are willing to ask questions often discover the deeper answer.', 'Opening the refrigerator without a plan still counts as a short expedition. Human determination is impressive, but alarms, snacks, and refrigerators remain worthy rivals. The first day of the week has done nothing wrong, yet everyone continues to question it.'),
    (1067, 'eng', 'long', 'When an unexpected problem appears, finding one improvement makes an ordinary day worth remembering, and when the goal feels distant, finish the next task within reach.', 'If we run now the scene will stop, but one more step can change the story. A scene that looks like an ending can still leave room for one decisive choice. There may be no right answer, but I am still choosing the people beside me.'),
    (1663, 'eng', 'short', 'After a small success, rest can be a wise part of progress rather than a sign of surrender.', 'The warmth of home makes time seem slower for a while.'),
    (1697, 'eng', 'long', 'When the familiar method fails, if focus disappears, close the extra screens and keep one task visible. Finishing a quick task now can remove hours of unnecessary worry.', 'An octopus has three hearts, and two of them move blood through the gills. Familiar landscapes contain scientific processes that careful observation can reveal. Trees exchange nutrients with fungi living in the soil around their roots.'),
    (1715, 'eng', 'long', 'Sincerity often appears in the simple habit of keeping a promised time, and gratitude should be spoken aloud even in the relationships that feel most familiar.', 'Short sessions repeated over time often build stronger memories than one long session. New knowledge becomes useful when we explain it, recall it, and test it in another setting. Explaining a difficult idea to someone else quickly reveals the missing pieces.'),
    (1779, 'kor', 'short', '도망칠 기회가 생겼을 때, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '늦은 오후의 햇살은 지친 마음에 작은 온기를 남긴다.'),
    (1781, 'kor', 'short', '비밀번호를 막 바꾸고 나면, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '창가에 머문 빗소리는 평범한 하루를 조금 특별하게 만든다.'),
    (1782, 'kor', 'short', '집으로 돌아가는 길에, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.', '천천히 번지는 노을은 잊고 있던 마음을 조용히 깨운다.'),
    (1783, 'kor', 'short', '월요일 아침에, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '골목을 스치는 저녁 바람은 복잡했던 생각을 잠시 쉬게 한다.'),
    (1784, 'kor', 'short', '평소와 다른 길을 걷다가, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.', '새벽에 깨어난 도시는 지나간 계절의 기억을 데려온다.'),
    (1787, 'kor', 'short', '당연하게 여긴 사실을 다시 보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '오래된 사진 한 장은 오늘을 천천히 바라보게 만든다.'),
    (1788, 'kor', 'short', '다시 시작하고 싶은 날에, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '우연히 들은 익숙한 노래는 말하지 못한 감정을 가만히 안아 준다.'),
    (1790, 'kor', 'short', '끝이라고 믿었던 장면에서, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '따뜻한 차 한 잔은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1793, 'kor', 'short', '비가 그친 오후에, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '한적한 산책길은 서두르던 걸음을 잠시 멈추게 한다.'),
    (1794, 'kor', 'short', '다시 시작하고 싶은 날에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '구름 사이로 나온 달빛은 사소한 행복이 가까이 있음을 알려 준다.'),
    (1795, 'kor', 'short', '긴 회의가 끝난 뒤에, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.', '비가 그친 뒤의 공기는 괜찮아질 내일을 조용히 기대하게 한다.'),
    (1797, 'kor', 'short', '익숙함이 무심함으로 바뀌기 전에, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '작은 화분의 새잎은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (1798, 'kor', 'short', '과학의 시선으로 세상을 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.', '책갈피에 남은 짧은 메모는 혼자였던 시간을 포근하게 채워 준다.'),
    (1799, 'kor', 'short', '다시 시작하고 싶은 날에, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '퇴근길에 마주친 하늘은 오래된 그리움을 부드럽게 흔든다.'),
    (1803, 'kor', 'short', '간식이 자꾸 생각날 때, 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '조용한 주말 아침은 지금 이 순간에 마음을 머물게 한다.'),
    (1804, 'kor', 'short', '다시 시작하고 싶은 날에, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '여름밤의 풀벌레 소리는 작은 용기를 다시 꺼내 들게 한다.'),
    (1805, 'kor', 'short', '집으로 돌아가는 길에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '첫눈이 내린 골목은 바쁜 하루에 느린 숨을 선물한다.'),
    (1806, 'kor', 'short', '계획이 어긋난 날에, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.', '바다에서 불어온 바람은 잊었던 미소를 천천히 되찾게 한다.'),
    (1810, 'kor', 'short', '새로운 일을 앞두고, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '낯익은 향기가 밴 옷은 멀어진 마음을 다시 돌아보게 한다.'),
    (1814, 'kor', 'short', '비밀번호를 막 바꾸고 나면, 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.', '오래 기다린 답장은 아무 말 없이도 깊은 위로가 된다.'),
    (1815, 'kor', 'short', '혼자 결정하기 어렵다면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.', '불을 낮춘 방 안은 내일의 나에게 다정한 약속을 건넨다.'),
    (1816, 'kor', 'short', '마음이 흔들릴 때마다 이 조용한 장면으로 돌아올 수 있을 것 같았다.', '커튼 사이의 아침빛은 흐릿했던 기억을 선명하게 비춘다.'),
    (1817, 'kor', 'short', '다시 시작하고 싶은 날에, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '비어 있는 옆자리는 무거운 마음을 한결 가볍게 만든다.'),
    (1819, 'kor', 'short', '가까운 사람과 대화할 때, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '천천히 식어 가는 커피는 조용한 설렘을 마음속에 피워 낸다.'),
    (1820, 'kor', 'short', '보이지 않는 원리를 생각하면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.', '멀리서 들리는 웃음은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (1821, 'kor', 'short', '새로운 일을 앞두고, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '한밤중의 작은 불빛은 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (1823, 'kor', 'short', '정답 없는 질문 앞에서도, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '낙엽이 쌓인 길은 평범한 순간의 소중함을 다시 알려 준다.'),
    (1825, 'kor', 'short', '월요일 아침이 찾아오면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '다정하게 건넨 인사는 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (1826, 'kor', 'short', '누군가의 도움이 필요할 때, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '문득 떠오른 이름은 지친 마음에 작은 온기를 남긴다.'),
    (1827, 'kor', 'short', '하루를 마무리하기 전에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '오늘의 고요한 틈은 평범한 하루를 조금 특별하게 만든다.'),
    (1828, 'kor', 'short', '누군가의 도움이 필요할 때, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.', '서랍 속 오래된 편지는 잊고 있던 마음을 조용히 깨운다.'),
    (1830, 'kor', 'short', '미안한 마음을 전해야 한다면, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '잔잔한 음악의 마지막 음은 복잡했던 생각을 잠시 쉬게 한다.'),
    (1831, 'kor', 'short', '과학의 시선으로 세상을 보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.', '늦은 오후의 햇살은 잊고 있던 마음을 조용히 깨운다.'),
    (1832, 'kor', 'short', '답을 찾기 어려운 순간에, 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.', '창가에 머문 빗소리는 복잡했던 생각을 잠시 쉬게 한다.'),
    (1836, 'kor', 'short', '정리를 시작하고 나면, 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.', '천천히 번지는 노을은 지나간 계절의 기억을 데려온다.'),
    (1837, 'kor', 'short', '집으로 돌아가는 길에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.', '골목을 스치는 저녁 바람은 오늘을 천천히 바라보게 만든다.'),
    (1838, 'kor', 'short', '답을 찾기 어려운 순간에, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '새벽에 깨어난 도시는 말하지 못한 감정을 가만히 안아 준다.'),
    (1839, 'kor', 'short', '누군가의 도움이 필요할 때, 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '오래된 사진 한 장은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1841, 'kor', 'short', '좋아하는 사람을 바라볼 때, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.', '우연히 들은 익숙한 노래는 서두르던 걸음을 잠시 멈추게 한다.'),
    (1842, 'kor', 'short', '당연하게 여긴 사실을 다시 보면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '따뜻한 차 한 잔은 사소한 행복이 가까이 있음을 알려 준다.'),
    (1843, 'kor', 'short', '긴 회의가 끝난 뒤에, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '한적한 산책길은 괜찮아질 내일을 조용히 기대하게 한다.'),
    (1845, 'kor', 'short', '마지막 불빛만 남았을 때, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.', '구름 사이로 나온 달빛은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (1847, 'kor', 'short', '냉장고 앞에 멈춰 서면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '비가 그친 뒤의 공기는 혼자였던 시간을 포근하게 채워 준다.'),
    (1848, 'kor', 'short', '익숙한 방법이 막히면, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '작은 화분의 새잎은 오래된 그리움을 부드럽게 흔든다.'),
    (1849, 'kor', 'short', '시간이 부족하게 느껴지면, 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '책갈피에 남은 짧은 메모는 지금 이 순간에 마음을 머물게 한다.'),
    (1850, 'kor', 'short', '다시 시작하고 싶은 날에, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.', '퇴근길에 마주친 하늘은 작은 용기를 다시 꺼내 들게 한다.'),
    (1852, 'kor', 'short', '서운한 마음이 생겼다면, 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '조용한 주말 아침은 바쁜 하루에 느린 숨을 선물한다.'),
    (1853, 'kor', 'short', '알려진 사실을 천천히 살펴보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '여름밤의 풀벌레 소리는 잊었던 미소를 천천히 되찾게 한다.'),
    (1854, 'kor', 'short', '잠깐 숨을 고르며, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.', '첫눈이 내린 골목은 멀어진 마음을 다시 돌아보게 한다.'),
    (1856, 'kor', 'short', '마지막 불빛만 남았을 때, 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '바다에서 불어온 바람은 아무 말 없이도 깊은 위로가 된다.'),
    (1858, 'kor', 'short', '비밀번호를 막 바꾸고 나면, 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '낯익은 향기가 밴 옷은 내일의 나에게 다정한 약속을 건넨다.'),
    (1859, 'kor', 'short', '월요일 아침에, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '오래 기다린 답장은 흐릿했던 기억을 선명하게 비춘다.'),
    (1860, 'kor', 'short', '실수가 마음에 남는다면, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '불을 낮춘 방 안은 무거운 마음을 한결 가볍게 만든다.'),
    (1861, 'kor', 'short', '월요일 아침에, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '커튼 사이의 아침빛은 조용한 설렘을 마음속에 피워 낸다.'),
    (1863, 'kor', 'short', '서운한 마음이 생겼다면, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '비어 있는 옆자리는 지나온 시간을 따뜻하게 이해하게 한다.'),
    (1864, 'kor', 'short', '세상이 움직이는 방식을 보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '천천히 식어 가는 커피는 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (1865, 'kor', 'short', '집으로 돌아가는 길에, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.', '멀리서 들리는 웃음은 평범한 순간의 소중함을 다시 알려 준다.'),
    (1867, 'kor', 'short', '도망칠 기회가 생겼을 때, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '한밤중의 작은 불빛은 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (1869, 'kor', 'short', '비밀번호를 막 바꾸고 나면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '낙엽이 쌓인 길은 지친 마음에 작은 온기를 남긴다.'),
    (1870, 'kor', 'short', '익숙한 방법이 막히면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.', '다정하게 건넨 인사는 평범한 하루를 조금 특별하게 만든다.'),
    (1871, 'kor', 'short', '비가 그친 오후에, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.', '문득 떠오른 이름은 잊고 있던 마음을 조용히 깨운다.'),
    (1872, 'kor', 'short', '익숙한 방법이 막히면, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.', '오늘의 고요한 틈은 복잡했던 생각을 잠시 쉬게 한다.'),
    (1874, 'kor', 'short', '미안한 마음을 전해야 한다면, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.', '서랍 속 오래된 편지는 지나간 계절의 기억을 데려온다.'),
    (1878, 'kor', 'short', '모두가 포기하라고 말해도, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.', '잔잔한 음악의 마지막 음은 오늘을 천천히 바라보게 만든다.'),
    (1880, 'kor', 'short', '간식이 자꾸 생각날 때, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.', '늦은 오후의 햇살은 지나간 계절의 기억을 데려온다.'),
    (1882, 'kor', 'short', '익숙한 방법이 막히면, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.', '창가에 머문 빗소리는 오늘을 천천히 바라보게 만든다.'),
    (1883, 'kor', 'short', '잠깐 숨을 고르며, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '천천히 번지는 노을은 말하지 못한 감정을 가만히 안아 준다.'),
    (1885, 'kor', 'short', '서운한 마음이 생겼다면, 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '골목을 스치는 저녁 바람은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1886, 'kor', 'short', '세상이 움직이는 방식을 보면, 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '새벽에 깨어난 도시는 서두르던 걸음을 잠시 멈추게 한다.'),
    (1887, 'kor', 'short', '계획이 어긋난 날에, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '오래된 사진 한 장은 사소한 행복이 가까이 있음을 알려 준다.'),
    (1889, 'kor', 'short', '도시가 갑자기 조용해지면, 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.', '우연히 들은 익숙한 노래는 괜찮아질 내일을 조용히 기대하게 한다.'),
    (1892, 'kor', 'short', '혼자 결정하기 어렵다면, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '따뜻한 차 한 잔은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (1893, 'kor', 'short', '마감이 가까워질수록, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '한적한 산책길은 혼자였던 시간을 포근하게 채워 준다.'),
    (1894, 'kor', 'short', '답을 찾기 어려운 순간에, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '구름 사이로 나온 달빛은 오래된 그리움을 부드럽게 흔든다.'),
    (1896, 'kor', 'short', '의견이 쉽게 좁혀지지 않으면, 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '비가 그친 뒤의 공기는 지금 이 순간에 마음을 머물게 한다.'),
    (1897, 'kor', 'short', '오랜 연구의 결과를 살펴보면, 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '작은 화분의 새잎은 작은 용기를 다시 꺼내 들게 한다.'),
    (1898, 'kor', 'short', '익숙한 방법이 막히면, 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.', '책갈피에 남은 짧은 메모는 바쁜 하루에 느린 숨을 선물한다.'),
    (1900, 'kor', 'short', '끝이라고 믿었던 장면에서, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.', '퇴근길에 마주친 하늘은 잊었던 미소를 천천히 되찾게 한다.'),
    (1902, 'kor', 'short', '일찍 자겠다고 다짐한 밤에는, 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '조용한 주말 아침은 멀어진 마음을 다시 돌아보게 한다.'),
    (1903, 'kor', 'short', '하루를 마무리하기 전에, 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '여름밤의 풀벌레 소리는 아무 말 없이도 깊은 위로가 된다.'),
    (1904, 'kor', 'short', '창문을 닫은 뒤에도 그날의 맑은 공기는 오래도록 마음속에 남아 있었다.', '첫눈이 내린 골목은 내일의 나에게 다정한 약속을 건넨다.'),
    (1905, 'kor', 'short', '익숙한 방법이 막히면, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.', '바다에서 불어온 바람은 흐릿했던 기억을 선명하게 비춘다.'),
    (1907, 'kor', 'short', '가까운 사람과 대화할 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '낯익은 향기가 밴 옷은 무거운 마음을 한결 가볍게 만든다.'),
    (1908, 'kor', 'short', '작은 단서에서 질문을 시작하면, 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '오래 기다린 답장은 조용한 설렘을 마음속에 피워 낸다.'),
    (1909, 'kor', 'short', '실수가 마음에 남는다면, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '불을 낮춘 방 안은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (1911, 'kor', 'short', '끝이라고 믿었던 장면에서, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.', '커튼 사이의 아침빛은 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (1914, 'kor', 'short', '마감이 가까워질수록, 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '비어 있는 옆자리는 평범한 순간의 소중함을 다시 알려 준다.'),
    (1915, 'kor', 'short', '잠깐 숨을 고르며, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.', '천천히 식어 가는 커피는 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (1916, 'kor', 'short', '비가 그친 오후에, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '멀리서 들리는 웃음은 지친 마음에 작은 온기를 남긴다.'),
    (1918, 'kor', 'short', '누군가 힘든 하루를 보냈다면, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '한밤중의 작은 불빛은 평범한 하루를 조금 특별하게 만든다.'),
    (1919, 'kor', 'short', '알려진 사실을 천천히 살펴보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '낙엽이 쌓인 길은 잊고 있던 마음을 조용히 깨운다.'),
    (1920, 'kor', 'short', '시간이 부족하게 느껴지면, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '다정하게 건넨 인사는 복잡했던 생각을 잠시 쉬게 한다.'),
    (1924, 'kor', 'short', '회의가 예상보다 길어지면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '문득 떠오른 이름은 지나간 계절의 기억을 데려온다.'),
    (1925, 'kor', 'short', '비가 그친 오후에, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '오늘의 고요한 틈은 오늘을 천천히 바라보게 만든다.'),
    (1926, 'kor', 'short', '조용한 주말 저녁에, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.', '서랍 속 오래된 편지는 말하지 못한 감정을 가만히 안아 준다.'),
    (1927, 'kor', 'short', '계획이 어긋난 날에, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '잔잔한 음악의 마지막 음은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1929, 'kor', 'short', '서운한 마음이 생겼다면, 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '늦은 오후의 햇살은 말하지 못한 감정을 가만히 안아 준다.'),
    (1930, 'kor', 'short', '자연을 자세히 관찰하면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.', '창가에 머문 빗소리는 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1931, 'kor', 'short', '월요일 아침에, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '천천히 번지는 노을은 서두르던 걸음을 잠시 멈추게 한다.'),
    (1935, 'kor', 'short', '냉장고 앞에 멈춰 서면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '골목을 스치는 저녁 바람은 사소한 행복이 가까이 있음을 알려 준다.'),
    (1936, 'kor', 'short', '익숙한 방법이 막히면, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '새벽에 깨어난 도시는 괜찮아질 내일을 조용히 기대하게 한다.'),
    (1937, 'kor', 'short', '다시 시작하고 싶은 날에, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '오래된 사진 한 장은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (1938, 'kor', 'short', '비가 그친 오후에, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.', '우연히 들은 익숙한 노래는 혼자였던 시간을 포근하게 채워 준다.'),
    (1941, 'kor', 'short', '익숙한 현상을 다시 바라보면, 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.', '따뜻한 차 한 잔은 오래된 그리움을 부드럽게 흔든다.'),
    (1942, 'kor', 'short', '작은 성공을 만났을 때, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '한적한 산책길은 지금 이 순간에 마음을 머물게 한다.'),
    (1944, 'kor', 'short', '길이 완전히 막힌 순간에도, 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '구름 사이로 나온 달빛은 작은 용기를 다시 꺼내 들게 한다.'),
    (1946, 'kor', 'short', '운동을 새로 결심하면, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.', '비가 그친 뒤의 공기는 바쁜 하루에 느린 숨을 선물한다.'),
    (1947, 'kor', 'short', '실수가 마음에 남는다면, 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '작은 화분의 새잎은 잊었던 미소를 천천히 되찾게 한다.'),
    (1948, 'kor', 'short', '평소와 다른 길을 걷다가, 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.', '책갈피에 남은 짧은 메모는 멀어진 마음을 다시 돌아보게 한다.'),
    (1949, 'kor', 'short', '새로운 일을 앞두고, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '퇴근길에 마주친 하늘은 아무 말 없이도 깊은 위로가 된다.'),
    (1952, 'kor', 'short', '익숙한 현상을 다시 바라보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '조용한 주말 아침은 내일의 나에게 다정한 약속을 건넨다.'),
    (1953, 'kor', 'short', '긴 회의가 끝난 뒤에, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '여름밤의 풀벌레 소리는 흐릿했던 기억을 선명하게 비춘다.'),
    (1955, 'kor', 'short', '돌아갈 길이 사라졌다면, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.', '첫눈이 내린 골목은 무거운 마음을 한결 가볍게 만든다.'),
    (1957, 'kor', 'short', '냉장고 앞에 멈춰 서면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '바다에서 불어온 바람은 조용한 설렘을 마음속에 피워 낸다.'),
    (1958, 'kor', 'short', '평소와 다른 길을 걷다가, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.', '낯익은 향기가 밴 옷은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (1959, 'kor', 'short', '내일도 완벽하지 않겠지만 오늘보다 조금 다정한 사람이 되고 싶어졌다.', '오래 기다린 답장은 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (1960, 'kor', 'short', '월요일 아침에, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.', '불을 낮춘 방 안은 평범한 순간의 소중함을 다시 알려 준다.'),
    (1962, 'kor', 'short', '좋아하는 사람을 바라볼 때, 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '커튼 사이의 아침빛은 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (1963, 'kor', 'short', '세상이 움직이는 방식을 보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.', '비어 있는 옆자리는 지친 마음에 작은 온기를 남긴다.'),
    (1966, 'kor', 'short', '중요한 선택을 앞두고, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.', '천천히 식어 가는 커피는 평범한 하루를 조금 특별하게 만든다.'),
    (1968, 'kor', 'short', '잃어버린 물건을 찾다 보면, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '멀리서 들리는 웃음은 잊고 있던 마음을 조용히 깨운다.'),
    (1969, 'kor', 'short', '평소와 다른 길을 걷다가, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '한밤중의 작은 불빛은 복잡했던 생각을 잠시 쉬게 한다.'),
    (1970, 'kor', 'short', '마감이 가까워질수록, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '낙엽이 쌓인 길은 지나간 계절의 기억을 데려온다.'),
    (1971, 'kor', 'short', '익숙한 방법이 막히면, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '다정하게 건넨 인사는 오늘을 천천히 바라보게 만든다.'),
    (1973, 'kor', 'short', '고마움을 표현하고 싶을 때, 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '문득 떠오른 이름은 말하지 못한 감정을 가만히 안아 준다.'),
    (1974, 'kor', 'short', '보이지 않는 원리를 생각하면, 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '오늘의 고요한 틈은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (1975, 'kor', 'short', '월요일 아침에, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.', '서랍 속 오래된 편지는 서두르던 걸음을 잠시 멈추게 한다.'),
    (1979, 'kor', 'short', '냉장고 앞에 멈춰 서면, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.', '잔잔한 음악의 마지막 음은 사소한 행복이 가까이 있음을 알려 준다.'),
    (1980, 'kor', 'short', '혼자 결정하기 어렵다면, 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '늦은 오후의 햇살은 서두르던 걸음을 잠시 멈추게 한다.'),
    (1981, 'kor', 'short', '조용한 주말 저녁에, 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.', '창가에 머문 빗소리는 사소한 행복이 가까이 있음을 알려 준다.'),
    (1982, 'kor', 'short', '예상 밖의 문제가 생기면, 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '천천히 번지는 노을은 괜찮아질 내일을 조용히 기대하게 한다.'),
    (1984, 'kor', 'short', '고마움을 표현하고 싶을 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '골목을 스치는 저녁 바람은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (1985, 'kor', 'short', '주변의 변화를 주의 깊게 보면, 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '새벽에 깨어난 도시는 혼자였던 시간을 포근하게 채워 준다.'),
    (1986, 'kor', 'short', '잠깐 숨을 고르며, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '오래된 사진 한 장은 오래된 그리움을 부드럽게 흔든다.'),
    (1988, 'kor', 'short', '서로의 손을 놓치기 전에, 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '우연히 들은 익숙한 노래는 지금 이 순간에 마음을 머물게 한다.'),
    (1991, 'kor', 'short', '답을 찾기 어려운 순간에, 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '따뜻한 차 한 잔은 작은 용기를 다시 꺼내 들게 한다.'),
    (1992, 'kor', 'short', '혼자 결정하기 어렵다면, 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.', '한적한 산책길은 바쁜 하루에 느린 숨을 선물한다.'),
    (1993, 'kor', 'short', '작은 성공을 만났을 때, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '구름 사이로 나온 달빛은 잊었던 미소를 천천히 되찾게 한다.'),
    (1995, 'kor', 'short', '익숙함이 무심함으로 바뀌기 전에, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '비가 그친 뒤의 공기는 멀어진 마음을 다시 돌아보게 한다.'),
    (1996, 'kor', 'short', '세상이 움직이는 방식을 보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '작은 화분의 새잎은 아무 말 없이도 깊은 위로가 된다.'),
    (1997, 'kor', 'short', '비가 그친 오후에, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '책갈피에 남은 짧은 메모는 내일의 나에게 다정한 약속을 건넨다.'),
    (1999, 'kor', 'short', '끝이라고 믿었던 장면에서, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '퇴근길에 마주친 하늘은 흐릿했던 기억을 선명하게 비춘다.'),
    (2000, 'kor', 'short', '일찍 자겠다고 다짐한 밤에는, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '조용한 주말 아침은 무거운 마음을 한결 가볍게 만든다.'),
    (2001, 'kor', 'short', '하루를 마무리하기 전에, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '여름밤의 풀벌레 소리는 조용한 설렘을 마음속에 피워 낸다.'),
    (2002, 'kor', 'short', '하루를 마무리하기 전에, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '첫눈이 내린 골목은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (2003, 'kor', 'short', '마감이 가까워질수록, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '바다에서 불어온 바람은 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (2004, 'kor', 'short', '가까운 사람과 대화할 때, 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.', '낯익은 향기가 밴 옷은 평범한 순간의 소중함을 다시 알려 준다.'),
    (2005, 'kor', 'short', '세상이 움직이는 방식을 보면, 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '오래 기다린 답장은 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (2006, 'kor', 'short', '긴 회의가 끝난 뒤에, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '불을 낮춘 방 안은 지친 마음에 작은 온기를 남긴다.'),
    (2008, 'kor', 'short', '끝이라고 믿었던 장면에서, 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.', '커튼 사이의 아침빛은 평범한 하루를 조금 특별하게 만든다.'),
    (2009, 'kor', 'short', '잃어버린 물건을 찾다 보면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '비어 있는 옆자리는 잊고 있던 마음을 조용히 깨운다.'),
    (2010, 'kor', 'short', '예상 밖의 문제가 생기면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.', '천천히 식어 가는 커피는 복잡했던 생각을 잠시 쉬게 한다.'),
    (2011, 'kor', 'short', '그 순간 모든 답을 찾지 못해도 괜찮다는 생각이 조용히 마음에 내려앉았다.', '멀리서 들리는 웃음은 지나간 계절의 기억을 데려온다.'),
    (2012, 'kor', 'short', '시간이 부족하게 느껴지면, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '한밤중의 작은 불빛은 오늘을 천천히 바라보게 만든다.'),
    (2013, 'kor', 'short', '미안한 마음을 전해야 한다면, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '낙엽이 쌓인 길은 말하지 못한 감정을 가만히 안아 준다.'),
    (2014, 'kor', 'short', '보이지 않는 원리를 생각하면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '다정하게 건넨 인사는 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (2015, 'kor', 'short', '평소와 다른 길을 걷다가, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.', '문득 떠오른 이름은 서두르던 걸음을 잠시 멈추게 한다.'),
    (2017, 'kor', 'short', '중요한 선택을 앞두고, 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '오늘의 고요한 틈은 사소한 행복이 가까이 있음을 알려 준다.'),
    (2018, 'kor', 'short', '운동을 새로 결심하면, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.', '서랍 속 오래된 편지는 괜찮아질 내일을 조용히 기대하게 한다.'),
    (2019, 'kor', 'short', '익숙한 방법이 막히면, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '잔잔한 음악의 마지막 음은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (2020, 'kor', 'short', '비가 그친 오후에, 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '늦은 오후의 햇살은 오래된 그리움을 부드럽게 흔든다.'),
    (2021, 'kor', 'short', '예상 밖의 문제가 생기면, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.', '창가에 머문 빗소리는 지금 이 순간에 마음을 머물게 한다.'),
    (2022, 'kor', 'short', '마음이 서로 엇갈린 순간에는, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.', '천천히 번지는 노을은 작은 용기를 다시 꺼내 들게 한다.'),
    (2023, 'kor', 'short', '주변의 변화를 주의 깊게 보면, 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.', '골목을 스치는 저녁 바람은 바쁜 하루에 느린 숨을 선물한다.'),
    (2024, 'kor', 'short', '잠깐 숨을 고르며, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.', '새벽에 깨어난 도시는 잊었던 미소를 천천히 되찾게 한다.'),
    (2026, 'kor', 'short', '중요한 선택을 앞두고, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.', '오래된 사진 한 장은 멀어진 마음을 다시 돌아보게 한다.'),
    (2028, 'kor', 'short', '누군가의 도움이 필요할 때, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '우연히 들은 익숙한 노래는 아무 말 없이도 깊은 위로가 된다.'),
    (2029, 'kor', 'short', '그날 이후 나는 평범한 순간을 예전보다 조금 더 오래 바라보게 되었다.', '따뜻한 차 한 잔은 내일의 나에게 다정한 약속을 건넨다.'),
    (2030, 'kor', 'short', '다시 시작하고 싶은 날에, 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '한적한 산책길은 흐릿했던 기억을 선명하게 비춘다.'),
    (2031, 'kor', 'short', '가까운 사람과 대화할 때, 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '구름 사이로 나온 달빛은 무거운 마음을 한결 가볍게 만든다.'),
    (2032, 'kor', 'short', '보이지 않는 원리를 생각하면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '비가 그친 뒤의 공기는 조용한 설렘을 마음속에 피워 낸다.'),
    (2033, 'kor', 'short', '마감이 가까워질수록, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.', '작은 화분의 새잎은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (2035, 'kor', 'short', '모두가 포기하라고 말해도, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.', '책갈피에 남은 짧은 메모는 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (2036, 'kor', 'short', '잠이 덜 깬 아침에는, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.', '퇴근길에 마주친 하늘은 평범한 순간의 소중함을 다시 알려 준다.'),
    (2037, 'kor', 'short', '다시 시작하고 싶은 날에, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '여름밤의 풀벌레 소리는 지친 마음에 작은 온기를 남긴다.'),
    (2038, 'kor', 'short', '예상 밖의 문제가 생기면, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '첫눈이 내린 골목은 평범한 하루를 조금 특별하게 만든다.'),
    (2039, 'kor', 'short', '평소와 다른 길을 걷다가, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.', '바다에서 불어온 바람은 잊고 있던 마음을 조용히 깨운다.'),
    (2040, 'kor', 'short', '마음이 서로 엇갈린 순간에는, 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.', '낯익은 향기가 밴 옷은 복잡했던 생각을 잠시 쉬게 한다.'),
    (2041, 'kor', 'short', '작은 단서에서 질문을 시작하면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '오래 기다린 답장은 지나간 계절의 기억을 데려온다.'),
    (2042, 'kor', 'short', '집으로 돌아가는 길에, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '불을 낮춘 방 안은 오늘을 천천히 바라보게 만든다.'),
    (2044, 'kor', 'short', '마지막 불빛만 남았을 때, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.', '커튼 사이의 아침빛은 말하지 못한 감정을 가만히 안아 준다.'),
    (2045, 'kor', 'short', '비밀번호를 막 바꾸고 나면, 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '비어 있는 옆자리는 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (2046, 'kor', 'short', '평소와 다른 길을 걷다가, 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '천천히 식어 가는 커피는 서두르던 걸음을 잠시 멈추게 한다.'),
    (2047, 'kor', 'short', '비가 그친 오후에, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '멀리서 들리는 웃음은 사소한 행복이 가까이 있음을 알려 준다.'),
    (2048, 'kor', 'short', '다시 시작하고 싶은 날에, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.', '한밤중의 작은 불빛은 괜찮아질 내일을 조용히 기대하게 한다.'),
    (2049, 'kor', 'short', '고마움을 표현하고 싶을 때, 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.', '낙엽이 쌓인 길은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (2050, 'kor', 'short', '세상이 움직이는 방식을 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.', '다정하게 건넨 인사는 혼자였던 시간을 포근하게 채워 준다.'),
    (2051, 'kor', 'short', '마감이 가까워질수록, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '문득 떠오른 이름은 오래된 그리움을 부드럽게 흔든다.'),
    (2053, 'kor', 'short', '서로의 손을 놓치기 전에, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.', '오늘의 고요한 틈은 지금 이 순간에 마음을 머물게 한다.'),
    (2054, 'kor', 'short', '월요일 아침이 찾아오면, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.', '서랍 속 오래된 편지는 작은 용기를 다시 꺼내 들게 한다.'),
    (2055, 'kor', 'short', '혼자 결정하기 어렵다면, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '잔잔한 음악의 마지막 음은 바쁜 하루에 느린 숨을 선물한다.'),
    (2056, 'kor', 'short', '익숙한 방법이 막히면, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '늦은 오후의 햇살은 작은 용기를 다시 꺼내 들게 한다.'),
    (2057, 'kor', 'short', '긴 회의가 끝난 뒤에, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '창가에 머문 빗소리는 바쁜 하루에 느린 숨을 선물한다.'),
    (2059, 'kor', 'short', '익숙한 현상을 다시 바라보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '천천히 번지는 노을은 잊었던 미소를 천천히 되찾게 한다.'),
    (2060, 'kor', 'short', '월요일 아침에, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '골목을 스치는 저녁 바람은 멀어진 마음을 다시 돌아보게 한다.'),
    (2062, 'kor', 'short', '서로의 손을 놓치기 전에, 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '새벽에 깨어난 도시는 아무 말 없이도 깊은 위로가 된다.'),
    (2063, 'kor', 'short', '잃어버린 물건을 찾다 보면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '오래된 사진 한 장은 내일의 나에게 다정한 약속을 건넨다.'),
    (2064, 'kor', 'short', '익숙한 방법이 막히면, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '우연히 들은 익숙한 노래는 흐릿했던 기억을 선명하게 비춘다.'),
    (2065, 'kor', 'short', '마감이 가까워질수록, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '따뜻한 차 한 잔은 무거운 마음을 한결 가볍게 만든다.'),
    (2066, 'kor', 'short', '하루를 마무리하기 전에, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '한적한 산책길은 조용한 설렘을 마음속에 피워 낸다.'),
    (2067, 'kor', 'short', '의견이 쉽게 좁혀지지 않으면, 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '구름 사이로 나온 달빛은 지나온 시간을 따뜻하게 이해하게 한다.'),
    (2068, 'kor', 'short', '자연을 자세히 관찰하면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '비가 그친 뒤의 공기는 오늘도 잘 버텼다고 말해 주는 듯하다.'),
    (2069, 'kor', 'short', '답을 찾기 어려운 순간에, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '작은 화분의 새잎은 평범한 순간의 소중함을 다시 알려 준다.'),
    (2071, 'kor', 'short', '길이 완전히 막힌 순간에도, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.', '책갈피에 남은 짧은 메모는 마음 깊은 곳에 맑은 숨을 불어넣는다.'),
    (2073, 'kor', 'short', '예상 밖의 문제가 생기면, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.', '퇴근길에 마주친 하늘은 지친 마음에 작은 온기를 남긴다.'),
    (2074, 'kor', 'short', '마감이 가까워질수록, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.', '조용한 주말 아침은 평범한 하루를 조금 특별하게 만든다.'),
    (2075, 'kor', 'short', '새로운 일을 앞두고, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '여름밤의 풀벌레 소리는 잊고 있던 마음을 조용히 깨운다.'),
    (2076, 'kor', 'short', '마음이 서로 엇갈린 순간에는, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.', '첫눈이 내린 골목은 복잡했던 생각을 잠시 쉬게 한다.'),
    (2077, 'kor', 'short', '익숙한 현상을 다시 바라보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '바다에서 불어온 바람은 지나간 계절의 기억을 데려온다.'),
    (2078, 'kor', 'short', '답을 찾기 어려운 순간에, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '낯익은 향기가 밴 옷은 오늘을 천천히 바라보게 만든다.'),
    (2080, 'kor', 'short', '길이 완전히 막힌 순간에도, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.', '오래 기다린 답장은 말하지 못한 감정을 가만히 안아 준다.'),
    (2081, 'kor', 'short', '회의가 예상보다 길어지면, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.', '불을 낮춘 방 안은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    (2082, 'kor', 'short', '월요일 아침에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.', '커튼 사이의 아침빛은 서두르던 걸음을 잠시 멈추게 한다.'),
    (2083, 'kor', 'short', '하루를 마무리하기 전에, 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '비어 있는 옆자리는 사소한 행복이 가까이 있음을 알려 준다.'),
    (2084, 'kor', 'short', '익숙한 방법이 막히면, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '천천히 식어 가는 커피는 괜찮아질 내일을 조용히 기대하게 한다.'),
    (2085, 'kor', 'short', '가까운 사람과 대화할 때, 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '멀리서 들리는 웃음은 익숙한 풍경을 새롭게 바라보게 한다.'),
    (2086, 'kor', 'short', '과학의 시선으로 세상을 보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '한밤중의 작은 불빛은 혼자였던 시간을 포근하게 채워 준다.'),
    (2087, 'kor', 'short', '다시 시작하고 싶은 날에, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '낙엽이 쌓인 길은 오래된 그리움을 부드럽게 흔든다.'),
    (2089, 'kor', 'short', '지나온 날들을 탓하는 대신 지금의 나를 천천히 안아 주기로 마음먹었다.', '다정하게 건넨 인사는 지금 이 순간에 마음을 머물게 한다.'),
    (2091, 'kor', 'short', '나는 늦게 도착한 마음도 진심이라면 충분히 소중하다고 생각하게 되었다.', '문득 떠오른 이름은 작은 용기를 다시 꺼내 들게 한다.'),
    (2093, 'kor', 'short', '돌아오는 길에는 아까보다 부드러운 표정으로 익숙한 거리를 바라볼 수 있었다.', '오늘의 고요한 틈은 바쁜 하루에 느린 숨을 선물한다.'),
    (2095, 'kor', 'short', '새로운 일을 앞두고, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.', '서랍 속 오래된 편지는 잊었던 미소를 천천히 되찾게 한다.'),
    (2096, 'kor', 'long', '회의가 예상보다 길어지면, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다, 그리고 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.'),
    (2097, 'kor', 'long', '평소와 다른 길을 걷다가, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 동시에 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.'),
    (2098, 'kor', 'long', '비가 그친 오후에, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 동시에 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.'),
    (2099, 'kor', 'long', '조용한 주말 저녁에, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다, 그리고 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.', '우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.'),
    (2100, 'kor', 'long', '마음이 서로 엇갈린 순간에는, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 동시에 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.'),
    (2101, 'kor', 'long', '익숙한 현상을 다시 바라보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다, 그리고 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.'),
    (2102, 'kor', 'long', '막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 답을 찾기 어려운 순간에, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '해가 기울 무렵 창문을 열자 선선한 바람이 방 안으로 천천히 들어왔다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 마음이 복잡할수록 답을 서두르기보다 지금의 감정을 온전히 바라볼 필요가 있다. 그래서 오늘만큼은 서두르지 않고 내 마음의 속도에 맞추어 걷기로 했다.'),
    (2103, 'kor', 'long', '책장을 천천히 넘기다가 지붕 위 첫눈은 괜찮아질 내일을 조용히 기대하게 한다. 차를 한 잔 마시며 우편함 속 편지는 지친 마음에 작은 온기를 남긴다. 책장을 천천히 넘기다가 정류장의 잔잔한 음악은 멀어진 마음을 다시 돌아보게 한다.', '속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.'),
    (2104, 'kor', 'long', '길이 완전히 막힌 순간에도, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아. 동시에 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.', '중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.'),
    (2105, 'kor', 'long', '정리를 시작하고 나면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 동시에 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.', '업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.'),
    (2106, 'kor', 'long', '실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다. 혼자 결정하기 어렵다면, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.', '냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.'),
    (2107, 'kor', 'long', '누군가의 도움이 필요할 때, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 동시에 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.', '오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.'),
    (2108, 'kor', 'long', '누군가의 도움이 필요할 때, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다. 동시에 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.'),
    (2109, 'kor', 'long', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 오랜 친구를 다시 만났을 때, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.', '한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.'),
    (2110, 'kor', 'long', '세상이 움직이는 방식을 보면, 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.'),
    (2111, 'kor', 'long', '업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 누군가의 도움이 필요할 때, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '비가 그친 골목에는 젖은 나무 냄새와 부드러운 저녁빛이 함께 머물렀다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 좋았던 기억은 붙잡을 때보다 편안히 놓아줄 때 더 따뜻한 모습으로 남는다. 오늘의 작은 위로가 내일을 시작할 힘이 되어 줄 것이라고 믿어 보기로 했다.'),
    (2112, 'kor', 'long', '한밤중의 작은 불빛은 조용한 설렘을 마음속에 피워 낸다. 해가 기울 무렵 문틈으로 든 바람은 바쁜 하루에 느린 숨을 선물한다. 오랜 약속을 마치고 정류장의 잔잔한 음악은 지나간 계절의 기억을 데려온다.', '실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.'),
    (2113, 'kor', 'long', '서로의 손을 놓치기 전에, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.', '기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.'),
    (2114, 'kor', 'long', '월요일 아침이 찾아오면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.'),
    (2115, 'kor', 'long', '평소와 다른 길을 걷다가, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다, 그리고 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.', '한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.'),
    (2116, 'kor', 'long', '실수가 마음에 남는다면, 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 동시에 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.'),
    (2117, 'kor', 'long', '실수가 마음에 남는다면, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자, 그리고 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.'),
    (2118, 'kor', 'long', '누군가 힘든 하루를 보냈다면, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다, 그리고 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.'),
    (2119, 'kor', 'long', '자연을 자세히 관찰하면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    (2120, 'kor', 'long', '계획이 어긋난 날에, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 동시에 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '조용한 카페 창가에 앉아 지나가는 사람들의 느린 표정을 바라보았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 오늘의 작은 선택이 당장은 보이지 않아도 내일의 분위기를 바꾸어 놓는다. 작은 변화라도 믿어 보기로 하자 마음 한편에 가벼운 설렘이 피어났다.'),
    (2121, 'kor', 'long', '책장을 천천히 넘기다가 거리의 느린 그림자는 지나온 시간을 따뜻하게 이해하게 한다. 집으로 돌아오는 길에 유리창의 빗방울은 혼자였던 시간을 포근하게 채워 준다. 골목을 스치는 저녁 바람은 바쁜 하루에 느린 숨을 선물한다.', '두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.'),
    (2122, 'kor', 'long', '마지막 불빛만 남았을 때, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해. 동시에 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.'),
    (2123, 'kor', 'long', '잃어버린 물건을 찾다 보면, 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다, 그리고 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    (2124, 'kor', 'long', '하루를 마무리하기 전에, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다. 동시에 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.'),
    (2125, 'kor', 'long', '작은 성공을 만났을 때, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다, 그리고 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.'),
    (2126, 'kor', 'long', '집으로 돌아가는 길에, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다, 그리고 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.'),
    (2127, 'kor', 'long', '진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 마음이 서로 엇갈린 순간에는, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.', '틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    (2128, 'kor', 'long', '당연하게 여긴 사실을 다시 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다, 그리고 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.'),
    (2129, 'kor', 'long', '반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 평소와 다른 길을 걷다가, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '퇴근길 버스 창문 너머로 붉은 노을이 길게 번지며 하루를 배웅했다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 우리는 큰 사건보다 사소한 장면 하나를 더 오래 기억하며 살아가기도 한다. 어둠이 깊어질수록 작은 불빛 하나가 더 선명해진다는 사실을 기억했다.'),
    (2130, 'kor', 'long', '음악이 끝난 뒤 유리창의 빗방울은 아무 말 없이도 깊은 위로가 된다. 잠에서 막 깨어나 우편함 속 편지는 오래된 그리움을 부드럽게 흔든다. 한참을 기다리다가 빈 의자 옆의 온기는 평범한 순간의 소중함을 다시 알려 준다.', '어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.'),
    (2131, 'kor', 'long', '돌아갈 길이 사라졌다면, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해, 그리고 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.'),
    (2132, 'kor', 'long', '간식이 자꾸 생각날 때, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 동시에 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.'),
    (2133, 'kor', 'long', '틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 계획이 어긋난 날에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.', '운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.'),
    (2134, 'kor', 'long', '답을 찾기 어려운 순간에, 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 동시에 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.'),
    (2135, 'kor', 'long', '누군가의 도움이 필요할 때, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.'),
    (2136, 'kor', 'long', '힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 가까운 사람과 대화할 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.'),
    (2137, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다, 그리고 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.'),
    (2138, 'kor', 'long', '긴 회의가 끝난 뒤에, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '주말 아침에 눈을 뜨니 커튼 사이로 맑은 햇살이 가만히 스며들었다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 평범한 하루를 견디게 하는 힘은 멀리 있는 목표보다 가까운 애정에서 온다. 내일도 완벽하지 않겠지만 오늘보다 조금 다정한 사람이 되고 싶어졌다.'),
    (2139, 'kor', 'long', '회의가 끝난 뒤 빈 의자 옆의 온기는 말하지 못한 감정을 가만히 안아 준다. 오랜 약속을 마치고 문틈으로 든 바람은 작은 용기를 다시 꺼내 들게 한다. 회의가 끝난 뒤 우편함 속 편지는 사소한 행복이 가까이 있음을 알려 준다.', '목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.'),
    (2140, 'kor', 'long', '정답 없는 질문 앞에서도, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 동시에 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.'),
    (2141, 'kor', 'long', '일찍 자겠다고 다짐한 밤에는, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 동시에 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.', '자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.'),
    (2142, 'kor', 'long', '혼자 결정하기 어렵다면, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다, 그리고 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.'),
    (2143, 'kor', 'long', '시간이 부족하게 느껴지면, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다. 동시에 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    (2144, 'kor', 'long', '누군가의 도움이 필요할 때, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 동시에 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.'),
    (2145, 'kor', 'long', '익숙함이 무심함으로 바뀌기 전에, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다, 그리고 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.'),
    (2146, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.'),
    (2147, 'kor', 'long', '평소와 다른 길을 걷다가, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '오래 걷던 산책길 끝에서 이름 모를 꽃 한 송이가 바람에 흔들리고 있었다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 한 번의 실패가 나를 설명하지 않으며 다시 시작하는 마음이 더 오래 남는다. 그날 이후 나는 평범한 순간을 예전보다 조금 더 오래 바라보게 되었다.'),
    (2148, 'kor', 'long', '비가 그친 뒤 거리의 느린 그림자는 평범한 하루를 조금 특별하게 만든다. 집으로 돌아오는 길에 우편함 속 편지는 괜찮아질 내일을 조용히 기대하게 한다. 해가 기울 무렵 화분 끝의 새잎은 오늘을 천천히 바라보게 만든다.', '기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    (2149, 'kor', 'long', '끝이라고 믿었던 장면에서, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.'),
    (2150, 'kor', 'long', '잠이 덜 깬 아침에는, 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다, 그리고 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.'),
    (2151, 'kor', 'long', '예상 밖의 문제가 생기면, 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다, 그리고 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.', '간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.'),
    (2152, 'kor', 'long', '예상 밖의 문제가 생기면, 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다, 그리고 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.'),
    (2153, 'kor', 'long', '하루를 마무리하기 전에, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다. 동시에 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.'),
    (2154, 'kor', 'long', '좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 오랜 친구를 다시 만났을 때, 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.', '배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    (2155, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 동시에 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.', '진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.'),
    (2156, 'kor', 'long', '계획이 어긋난 날에, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 동시에 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '늦은 밤 책장을 덮자 방 안에는 시계 소리와 잔잔한 음악만 남았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 지나간 시간을 바꿀 수는 없어도 그 시간을 바라보는 마음은 달라질 수 있다. 한참을 머물다 일어서는 발걸음은 이상할 만큼 가볍고 단단해져 있었다.'),
    (2157, 'kor', 'long', '바람 소리에 멈춰서 빈 의자 옆의 온기는 익숙한 풍경을 새롭게 바라보게 한다. 한참을 기다리다가 창가에서 본 햇살은 혼자였던 시간을 포근하게 채워 준다. 책장을 천천히 넘기다가 거리의 느린 그림자는 잊고 있던 마음을 조용히 깨운다.', '잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.'),
    (2158, 'kor', 'long', '길이 완전히 막힌 순간에도, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어, 그리고 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    (2159, 'kor', 'long', '간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 간식이 자꾸 생각날 때, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    (2160, 'kor', 'long', '긴 회의가 끝난 뒤에, 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다. 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.'),
    (2161, 'kor', 'long', '혼자 결정하기 어렵다면, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자, 그리고 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.'),
    (2162, 'kor', 'long', '조용한 주말 저녁에, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자, 그리고 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.'),
    (2163, 'kor', 'long', '서운한 마음이 생겼다면, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다, 그리고 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.'),
    (2164, 'kor', 'long', '주변의 변화를 주의 깊게 보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 동시에 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.', '좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.'),
    (2165, 'kor', 'long', '동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 시간이 부족하게 느껴지면, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '첫눈이 내린 거리는 익숙한 풍경을 새하얀 장면으로 천천히 바꾸어 놓았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 마음에 쌓인 피로는 아무것도 하지 않는 고요한 시간 속에서 천천히 풀린다. 아직 오지 않은 날들을 걱정하기보다 지금 곁에 있는 온기를 믿기로 했다.'),
    (2166, 'kor', 'long', '차를 한 잔 마시며 문틈으로 든 바람은 잊었던 미소를 천천히 되찾게 한다. 구름이 걷힌 순간 우편함 속 편지는 지친 마음에 작은 온기를 남긴다. 낯선 동네를 지나다가 길모퉁이의 작은 꽃은 잊었던 미소를 천천히 되찾게 한다.', '아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.'),
    (2167, 'kor', 'long', '서로의 손을 놓치기 전에, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해, 그리고 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.', '좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    (2168, 'kor', 'long', '운동을 새로 결심하면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다, 그리고 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.', '좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.'),
    (2169, 'kor', 'long', '집으로 돌아가는 길에, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 동시에 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.'),
    (2170, 'kor', 'long', '실수가 마음에 남는다면, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 동시에 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    (2171, 'kor', 'long', '익숙한 방법이 막히면, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 동시에 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    (2172, 'kor', 'long', '의견이 쉽게 좁혀지지 않으면, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 동시에 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.'),
    (2173, 'kor', 'long', '작은 단서에서 질문을 시작하면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.'),
    (2174, 'kor', 'long', '실수가 마음에 남는다면, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다, 그리고 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '바닷가에 앉아 밀려왔다 멀어지는 파도의 리듬을 오래 바라보았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 슬픔을 억지로 지우기보다 충분히 지나가게 두는 것이 진짜 회복에 가깝다. 익숙한 하루 안에도 아직 발견하지 못한 아름다움이 많다는 것을 알게 되었다.'),
    (2175, 'kor', 'long', '새로운 길을 걷다가 책상 위 짧은 메모는 마음 깊은 곳에 맑은 숨을 불어넣는다. 책장을 천천히 넘기다가 하늘에 남은 노을은 잊고 있던 마음을 조용히 깨운다. 오랜 약속을 마치고 멀리 켜진 불빛은 잊었던 미소를 천천히 되찾게 한다.', '스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.'),
    (2176, 'kor', 'long', '도망칠 기회가 생겼을 때, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 동시에 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.'),
    (2177, 'kor', 'long', '회의가 예상보다 길어지면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다. 동시에 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.'),
    (2178, 'kor', 'long', '계획이 어긋난 날에, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 동시에 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.', '일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    (2179, 'kor', 'long', '시간이 부족하게 느껴지면, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.'),
    (2180, 'kor', 'long', '답을 찾기 어려운 순간에, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다, 그리고 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.'),
    (2181, 'kor', 'long', '서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 의견이 쉽게 좁혀지지 않으면, 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.'),
    (2182, 'kor', 'long', '번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 오랜 연구의 결과를 살펴보면, 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.'),
    (2183, 'kor', 'long', '작은 성공을 만났을 때, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다, 그리고 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '따뜻한 차를 우려 놓고 창밖의 빗방울이 흘러내리는 모습을 지켜보았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 누군가의 다정한 한마디는 생각보다 오래 남아 힘든 날의 중심을 잡아 준다. 나는 충분히 쉬어 가는 일도 앞으로 나아가는 방법임을 받아들이기로 했다.'),
    (2184, 'kor', 'long', '새벽에 깨어난 도시는 잊었던 미소를 천천히 되찾게 한다. 낯선 동네를 지나다가 거리의 느린 그림자는 지금 이 순간에 마음을 머물게 한다. 오랜 약속을 마치고 정류장의 잔잔한 음악은 익숙한 풍경을 새롭게 바라보게 한다.', '완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.'),
    (2185, 'kor', 'long', '마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 끝이라고 믿었던 장면에서, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.'),
    (2186, 'kor', 'long', '잠이 덜 깬 아침에는, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 동시에 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.'),
    (2187, 'kor', 'long', '모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 하루를 마무리하기 전에, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.'),
    (2188, 'kor', 'long', '기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 평소와 다른 길을 걷다가, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.', '문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.'),
    (2189, 'kor', 'long', '누군가의 도움이 필요할 때, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.'),
    (2190, 'kor', 'long', '누군가 힘든 하루를 보냈다면, 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 동시에 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.'),
    (2191, 'kor', 'long', '세상이 움직이는 방식을 보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.'),
    (2192, 'kor', 'long', '조용한 주말 저녁에, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다, 그리고 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '서랍을 정리하다 발견한 사진 속에서 오래전의 내가 환하게 웃고 있었다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 완벽하지 않은 모습까지 받아들일 때 비로소 나다운 방향이 선명해진다. 말로 설명하기 어려운 감정은 그대로 두어도 충분히 아름다울 수 있었다.'),
    (2193, 'kor', 'long', '음악이 끝난 뒤 화분 끝의 새잎은 평범한 하루를 조금 특별하게 만든다. 오랜 약속을 마치고 창가에서 본 햇살은 잊었던 미소를 천천히 되찾게 한다. 구름이 걷힌 순간 하늘에 남은 노을은 흐릿했던 기억을 선명하게 비춘다.', '속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.'),
    (2194, 'kor', 'long', '길이 완전히 막힌 순간에도, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 동시에 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.'),
    (2195, 'kor', 'long', '정리를 시작하고 나면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 동시에 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.'),
    (2196, 'kor', 'long', '익숙한 방법이 막히면, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 동시에 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.'),
    (2197, 'kor', 'long', '하루를 마무리하기 전에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 동시에 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.'),
    (2198, 'kor', 'long', '집으로 돌아가는 길에, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자. 동시에 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.'),
    (2199, 'kor', 'long', '고마움을 표현하고 싶을 때, 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다, 그리고 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.', '한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.'),
    (2200, 'kor', 'long', '익숙한 현상을 다시 바라보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 동시에 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    (2201, 'kor', 'long', '작은 성공을 만났을 때, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '새벽 공기가 차가워 창문을 닫으려다 희미하게 밝아 오는 하늘을 보았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 혼자 보내는 시간은 외로움이 아니라 내 목소리를 다시 듣는 여백이 된다. 나는 그 고요를 오래 기억해 두었다가 지친 날에 다시 꺼내 보기로 했다.'),
    (2202, 'kor', 'long', '불을 낮춘 다음 빈 의자 옆의 온기는 작은 용기를 다시 꺼내 들게 한다. 오랜 약속을 마치고 정류장의 잔잔한 음악은 지친 마음에 작은 온기를 남긴다. 잠에서 막 깨어나 정류장의 잔잔한 음악은 흐릿했던 기억을 선명하게 비춘다.', '실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.'),
    (2203, 'kor', 'long', '정답 없는 질문 앞에서도, 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야, 그리고 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.'),
    (2204, 'kor', 'long', '월요일 아침이 찾아오면, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다, 그리고 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    (2205, 'kor', 'long', '잠깐 숨을 고르며, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다, 그리고 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.'),
    (2206, 'kor', 'long', '다시 시작하고 싶은 날에, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다, 그리고 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.'),
    (2207, 'kor', 'long', '혼자 결정하기 어렵다면, 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자, 그리고 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.'),
    (2208, 'kor', 'long', '좋아하는 사람을 바라볼 때, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다, 그리고 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    (2209, 'kor', 'long', '과학의 시선으로 세상을 보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 동시에 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.'),
    (2210, 'kor', 'long', '월요일 아침에, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다, 그리고 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '낙엽이 수북한 길을 걸을 때마다 발끝에서 바스락거리는 소리가 났다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 매일 같은 길을 걷더라도 마음의 속도를 늦추면 전에는 없던 풍경이 보인다. 나는 늦게 도착한 마음도 진심이라면 충분히 소중하다고 생각하게 되었다.'),
    (2211, 'kor', 'long', '차를 한 잔 마시며 화분 끝의 새잎은 잊고 있던 마음을 조용히 깨운다. 책갈피에 남은 짧은 메모는 복잡했던 생각을 잠시 쉬게 한다. 비가 그친 뒤 화분 끝의 새잎은 내일의 나에게 다정한 약속을 건넨다.', '두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.'),
    (2212, 'kor', 'long', '도망칠 기회가 생겼을 때, 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼, 그리고 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.'),
    (2213, 'kor', 'long', '월요일 아침이 찾아오면, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다, 그리고 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.'),
    (2214, 'kor', 'long', '실수가 마음에 남는다면, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다, 그리고 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.'),
    (2215, 'kor', 'long', '시간이 부족하게 느껴지면, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 동시에 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.'),
    (2216, 'kor', 'long', '집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 시간이 부족하게 느껴지면, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.'),
    (2217, 'kor', 'long', '가까운 사람과 대화할 때, 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.'),
    (2218, 'kor', 'long', '구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 세상이 움직이는 방식을 보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.', '서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.'),
    (2219, 'kor', 'long', '마감이 가까워질수록, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다, 그리고 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '오랜만에 찾은 동네에는 달라진 간판과 그대로인 골목이 나란히 있었다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 계절이 변하듯 사람의 마음도 머물고 떠나며 새로운 자리를 만들어 간다. 돌아오는 길에는 아까보다 부드러운 표정으로 익숙한 거리를 바라볼 수 있었다.'),
    (2220, 'kor', 'long', '오늘의 고요한 틈은 잊고 있던 마음을 조용히 깨운다. 구름 사이로 나온 달빛은 지나온 시간을 따뜻하게 이해하게 한다. 차를 한 잔 마시며 유리창의 빗방울은 평범한 순간의 소중함을 다시 알려 준다.', '어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.'),
    (2221, 'kor', 'long', '길이 완전히 막힌 순간에도, 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어, 그리고 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.'),
    (2222, 'kor', 'long', '회의가 예상보다 길어지면, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다. 동시에 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.', '완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.'),
    (2223, 'kor', 'long', '답을 찾기 어려운 순간에, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.', '운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.'),
    (2224, 'kor', 'long', '계획이 어긋난 날에, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 동시에 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    (2225, 'kor', 'long', '누군가의 도움이 필요할 때, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다, 그리고 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.', '사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.'),
    (2226, 'kor', 'long', '서운한 마음이 생겼다면, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 동시에 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.'),
    (2227, 'kor', 'long', '보이지 않는 원리를 생각하면, 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다, 그리고 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.'),
    (2228, 'kor', 'long', '집으로 돌아가는 길에, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 동시에 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.', '작은 화분 끝에 돋아난 새잎이 아침 햇빛을 받아 투명하게 빛나고 있었다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 오래된 꿈은 잊힌 것이 아니라 다시 꺼낼 알맞은 순간을 기다리고 있을지 모른다. 다시 걷기 시작하자 멈춰 있던 생각들도 제자리를 찾아 천천히 흘러갔다.'),
    (2229, 'kor', 'long', '구름이 걷힌 순간 길모퉁이의 작은 꽃은 사소한 행복이 가까이 있음을 알려 준다. 오랜 약속을 마치고 물 위에 번진 달빛은 혼자였던 시간을 포근하게 채워 준다. 바람 소리에 멈춰서 거리의 느린 그림자는 잊었던 미소를 천천히 되찾게 한다.', '목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    (2230, 'kor', 'long', '중요한 선택을 앞두고, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아, 그리고 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.', '대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.'),
    (2231, 'kor', 'long', '잃어버린 물건을 찾다 보면, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다, 그리고 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.', '자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.'),
    (2232, 'kor', 'long', '마감이 가까워질수록, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다, 그리고 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.'),
    (2233, 'kor', 'long', '예상 밖의 문제가 생기면, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.'),
    (2234, 'kor', 'long', '하루를 마무리하기 전에, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.'),
    (2235, 'kor', 'long', '좋아하는 사람을 바라볼 때, 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다, 그리고 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    (2236, 'kor', 'long', '달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 익숙한 현상을 다시 바라보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.'),
    (2237, 'kor', 'long', '혼자 결정하기 어렵다면, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.', '저녁 식사를 마친 뒤 불을 낮추니 집 안의 시간이 조금 느리게 흐르는 듯했다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 모든 관계에는 말보다 침묵으로 서로를 이해해야 하는 순간이 찾아온다. 그 순간 모든 답을 찾지 못해도 괜찮다는 생각이 조용히 마음에 내려앉았다.'),
    (2238, 'kor', 'long', '음악이 끝난 뒤 멀리 켜진 불빛은 내일의 나에게 다정한 약속을 건넨다. 새로운 길을 걷다가 창가에서 본 햇살은 복잡했던 생각을 잠시 쉬게 한다. 집으로 돌아오는 길에 빈 의자 옆의 온기는 내일의 나에게 다정한 약속을 건넨다.', '기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.'),
    (2239, 'kor', 'long', '마지막 불빛만 남았을 때, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어. 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.', '새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    (2240, 'kor', 'long', '한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 비밀번호를 막 바꾸고 나면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    (2241, 'kor', 'long', '긴 회의가 끝난 뒤에, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.'),
    (2242, 'kor', 'long', '계획이 어긋난 날에, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자, 그리고 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.', '누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.'),
    (2243, 'kor', 'long', '평소와 다른 길을 걷다가, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 동시에 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.'),
    (2244, 'kor', 'long', '좋아하는 사람을 바라볼 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 동시에 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.'),
    (2245, 'kor', 'long', '기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다. 익숙한 현상을 다시 바라보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.'),
    (2246, 'kor', 'long', '작은 성공을 만났을 때, 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '우연히 재생된 옛 노래가 잊고 있던 어느 계절의 공기를 데려왔다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 기다림은 답이 없는 시간이 아니라 마음이 스스로를 정리하는 과정일 수 있다. 마음이 흔들릴 때마다 이 조용한 장면으로 돌아올 수 있을 것 같았다.'),
    (2247, 'kor', 'long', '한참을 기다리다가 골목에서 만난 바람은 조용한 설렘을 마음속에 피워 낸다. 바람 소리에 멈춰서 창가에서 본 햇살은 마음 한쪽에 잔잔한 여운을 남긴다. 음악이 끝난 뒤 길모퉁이의 작은 꽃은 지나온 시간을 따뜻하게 이해하게 한다.', '잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.'),
    (2248, 'kor', 'long', '끝이라고 믿었던 장면에서, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어, 그리고 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    (2249, 'kor', 'long', '냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 잃어버린 물건을 찾다 보면, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.'),
    (2250, 'kor', 'long', '긴 회의가 끝난 뒤에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다, 그리고 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.', '비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.'),
    (2251, 'kor', 'long', '답을 찾기 어려운 순간에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    (2252, 'kor', 'long', '다시 시작하고 싶은 날에, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    (2253, 'kor', 'long', '마음이 서로 엇갈린 순간에는, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.'),
    (2254, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 동시에 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.'),
    (2255, 'kor', 'long', '작은 성공을 만났을 때, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 동시에 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '한강을 따라 걷는 동안 멀리 켜진 불빛들이 물 위에서 조용히 흔들렸다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 행복은 대단한 장면보다 좋아하는 사람과 나눈 짧은 웃음 속에 자주 숨어 있다. 지나온 날들을 탓하는 대신 지금의 나를 천천히 안아 주기로 마음먹었다.'),
    (2256, 'kor', 'long', '구름이 걷힌 순간 유리창의 빗방울은 지친 마음에 작은 온기를 남긴다. 문득 떠오른 이름은 오늘을 천천히 바라보게 만든다. 구름이 걷힌 순간 우편함 속 편지는 서두르던 걸음을 잠시 멈추게 한다.', '아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.'),
    (2257, 'kor', 'long', '모두가 포기하라고 말해도, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 동시에 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.', '좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.'),
    (2258, 'kor', 'long', '회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 일찍 자겠다고 다짐한 밤에는, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.', '좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.'),
    (2259, 'kor', 'long', '새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 익숙한 방법이 막히면, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    (2260, 'kor', 'long', '집으로 돌아가는 길에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 동시에 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.'),
    (2261, 'kor', 'long', '혼자 결정하기 어렵다면, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자, 그리고 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.'),
    (2262, 'kor', 'long', '좋아하는 사람을 바라볼 때, 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다. 동시에 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.'),
    (2263, 'kor', 'long', '보이지 않는 원리를 생각하면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 동시에 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.', '대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.'),
    (2264, 'kor', 'long', '실수가 마음에 남는다면, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '약속보다 일찍 도착한 나는 빈 의자에 앉아 따뜻한 커피를 천천히 마셨다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 조금 늦어도 괜찮다는 믿음은 멈추지 않고 나아갈 수 있는 여유를 만들어 준다. 끝이라고 생각했던 자리에서도 새로운 시작은 조용히 자라고 있었다.'),
    (2265, 'kor', 'long', '비가 그친 뒤 지붕 위 첫눈은 잊었던 미소를 천천히 되찾게 한다. 불을 낮춘 방 안은 말하지 못한 감정을 가만히 안아 준다. 책장을 천천히 넘기다가 멀리 켜진 불빛은 평범한 순간의 소중함을 다시 알려 준다.', '스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.'),
    (2266, 'kor', 'long', '도망칠 기회가 생겼을 때, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 동시에 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.', '일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.'),
    (2267, 'kor', 'long', '잠이 덜 깬 아침에는, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다. 동시에 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.'),
    (2268, 'kor', 'long', '어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 예상 밖의 문제가 생기면, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.', '일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.'),
    (2269, 'kor', 'long', '다시 시작하고 싶은 날에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.'),
    (2270, 'kor', 'long', '시간이 부족하게 느껴지면, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다, 그리고 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.'),
    (2271, 'kor', 'long', '고마움을 표현하고 싶을 때, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 동시에 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.'),
    (2272, 'kor', 'long', '사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 작은 단서에서 질문을 시작하면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.'),
    (2273, 'kor', 'long', '평소와 다른 길을 걷다가, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '비어 있던 우편함에서 반가운 편지 한 통을 발견하고 한참을 바라보았다. 평범한 풍경은 마음의 속도를 바꾸는 작은 계기가 되기도 한다. 가까운 사람일수록 익숙함 뒤에 숨은 고마움을 자주 표현해야 한다. 창문을 닫은 뒤에도 그날의 맑은 공기는 오래도록 마음속에 남아 있었다.'),
    (2274, 'kor', 'long', '해가 기울 무렵 길모퉁이의 작은 꽃은 평범한 하루를 조금 특별하게 만든다. 차를 한 잔 마시며 물 위에 번진 달빛은 조용한 설렘을 마음속에 피워 낸다. 책장을 천천히 넘기다가 창가에서 본 햇살은 내일의 나에게 다정한 약속을 건넨다.', '완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.'),
    (2275, 'kor', 'long', '돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어. 도시가 갑자기 조용해지면, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.', '해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.'),
    (2276, 'kor', 'long', '간식이 자꾸 생각날 때, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다, 그리고 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.', '좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.'),
    (2277, 'kor', 'long', '다시 시작하고 싶은 날에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 동시에 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.'),
    (2278, 'kor', 'long', '답을 찾기 어려운 순간에, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 동시에 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.'),
    (2279, 'kor', 'long', '긴 회의가 끝난 뒤에, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다, 그리고 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.', '우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.'),
    (2280, 'kor', 'long', '오랜 친구를 다시 만났을 때, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다, 그리고 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.'),
    (2281, 'kor', 'long', '과학의 시선으로 세상을 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    (2282, 'kor', 'long', '답을 찾기 어려운 순간에, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다. 동시에 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '해가 기울 무렵 창문을 열자 선선한 바람이 방 안으로 천천히 들어왔다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 누군가의 다정한 한마디는 생각보다 오래 남아 힘든 날의 중심을 잡아 준다. 그 순간 모든 답을 찾지 못해도 괜찮다는 생각이 조용히 마음에 내려앉았다.'),
    (2283, 'kor', 'long', '새벽에 깨어난 도시는 익숙한 풍경을 새롭게 바라보게 한다. 불을 낮춘 다음 거리의 느린 그림자는 평범한 순간의 소중함을 다시 알려 준다. 새로운 길을 걷다가 거리의 느린 그림자는 작은 용기를 다시 꺼내 들게 한다.', '속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.'),
    (2284, 'kor', 'long', '돌아갈 길이 사라졌다면, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까, 그리고 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.', '중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.'),
    (2285, 'kor', 'long', '일찍 자겠다고 다짐한 밤에는, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다. 동시에 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    (2286, 'kor', 'long', '예상 밖의 문제가 생기면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다, 그리고 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.'),
    (2287, 'kor', 'long', '새로운 일을 앞두고, 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 동시에 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.', '오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.'),
    (2288, 'kor', 'long', '시간이 부족하게 느껴지면, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자, 그리고 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.'),
    (2289, 'kor', 'long', '가까운 사람과 대화할 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.', '한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    (2290, 'kor', 'long', '벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 자연을 자세히 관찰하면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.'),
    (2291, 'kor', 'long', '다시 시작하고 싶은 날에, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다, 그리고 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '비가 그친 골목에는 젖은 나무 냄새와 부드러운 저녁빛이 함께 머물렀다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 완벽하지 않은 모습까지 받아들일 때 비로소 나다운 방향이 선명해진다. 마음이 흔들릴 때마다 이 조용한 장면으로 돌아올 수 있을 것 같았다.'),
    (2292, 'kor', 'long', '불을 낮춘 다음 골목에서 만난 바람은 마음 한쪽에 잔잔한 여운을 남긴다. 한참을 기다리다가 우편함 속 편지는 잊었던 미소를 천천히 되찾게 한다. 책장을 천천히 넘기다가 멀리 켜진 불빛은 괜찮아질 내일을 조용히 기대하게 한다.', '실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.'),
    (2293, 'kor', 'long', '정답 없는 질문 앞에서도, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 동시에 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.'),
    (2294, 'kor', 'long', '월요일 아침이 찾아오면, 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 동시에 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.'),
    (2295, 'kor', 'long', '익숙한 방법이 막히면, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 동시에 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.'),
    (2296, 'kor', 'long', '답을 찾기 어려운 순간에, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 동시에 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.'),
    (2297, 'kor', 'long', '시간이 부족하게 느껴지면, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.'),
    (2298, 'kor', 'long', '미안한 마음을 전해야 한다면, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 동시에 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.'),
    (2299, 'kor', 'long', '세상이 움직이는 방식을 보면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.'),
    (2300, 'kor', 'long', '하루를 마무리하기 전에, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다, 그리고 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '조용한 카페 창가에 앉아 지나가는 사람들의 느린 표정을 바라보았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 혼자 보내는 시간은 외로움이 아니라 내 목소리를 다시 듣는 여백이 된다. 지나온 날들을 탓하는 대신 지금의 나를 천천히 안아 주기로 마음먹었다.'),
    (2301, 'kor', 'long', '잠에서 막 깨어나 골목에서 만난 바람은 마음 깊은 곳에 맑은 숨을 불어넣는다. 비가 그친 뒤 길모퉁이의 작은 꽃은 오래된 그리움을 부드럽게 흔든다. 잠에서 막 깨어나 창가에서 본 햇살은 오늘을 천천히 바라보게 만든다.', '두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.'),
    (2302, 'kor', 'long', '정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 돌아갈 길이 사라졌다면, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.'),
    (2303, 'kor', 'long', '월요일 아침이 찾아오면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.'),
    (2304, 'kor', 'long', '새로운 일을 앞두고, 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다, 그리고 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.'),
    (2305, 'kor', 'long', '답을 찾기 어려운 순간에, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다, 그리고 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    (2306, 'kor', 'long', '실수가 마음에 남는다면, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자, 그리고 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.', '번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.'),
    (2307, 'kor', 'long', '미안한 마음을 전해야 한다면, 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 동시에 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.'),
    (2308, 'kor', 'long', '알려진 사실을 천천히 살펴보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다, 그리고 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.'),
    (2309, 'kor', 'long', '마감이 가까워질수록, 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다. 동시에 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '퇴근길 버스 창문 너머로 붉은 노을이 길게 번지며 하루를 배웅했다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 매일 같은 길을 걷더라도 마음의 속도를 늦추면 전에는 없던 풍경이 보인다. 끝이라고 생각했던 자리에서도 새로운 시작은 조용히 자라고 있었다.'),
    (2310, 'kor', 'long', '낯선 동네를 지나다가 골목에서 만난 바람은 오래된 그리움을 부드럽게 흔든다. 해가 기울 무렵 책상 위 짧은 메모는 바쁜 하루에 느린 숨을 선물한다. 비가 그친 뒤 지붕 위 첫눈은 무거운 마음을 한결 가볍게 만든다.', '어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    (2311, 'kor', 'long', '돌아갈 길이 사라졌다면, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아, 그리고 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.'),
    (2312, 'kor', 'long', '간식이 자꾸 생각날 때, 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다, 그리고 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.'),
    (2313, 'kor', 'long', '마감이 가까워질수록, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 동시에 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.'),
    (2314, 'kor', 'long', '혼자 결정하기 어렵다면, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.', '우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.'),
    (2315, 'kor', 'long', '답을 찾기 어려운 순간에, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 동시에 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.'),
    (2316, 'kor', 'long', '가까운 사람과 대화할 때, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 동시에 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    (2317, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 동시에 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.'),
    (2318, 'kor', 'long', '어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 하루를 마무리하기 전에, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '주말 아침에 눈을 뜨니 커튼 사이로 맑은 햇살이 가만히 스며들었다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 계절이 변하듯 사람의 마음도 머물고 떠나며 새로운 자리를 만들어 간다. 창문을 닫은 뒤에도 그날의 맑은 공기는 오래도록 마음속에 남아 있었다.'),
    (2319, 'kor', 'long', '음악이 끝난 뒤 창가에서 본 햇살은 지나온 시간을 따뜻하게 이해하게 한다. 오랜 약속을 마치고 지붕 위 첫눈은 복잡했던 생각을 잠시 쉬게 한다. 새로운 길을 걷다가 우편함 속 편지는 오늘을 천천히 바라보게 만든다.', '목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.'),
    (2320, 'kor', 'long', '도시가 갑자기 조용해지면, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야, 그리고 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.', '대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    (2321, 'kor', 'long', '월요일 아침이 찾아오면, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다, 그리고 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    (2322, 'kor', 'long', '한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 잠깐 숨을 고르며, 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.'),
    (2323, 'kor', 'long', '답을 찾기 어려운 순간에, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.'),
    (2324, 'kor', 'long', '십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다. 다시 시작하고 싶은 날에, 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.'),
    (2325, 'kor', 'long', '의견이 쉽게 좁혀지지 않으면, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.', '질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.'),
    (2326, 'kor', 'long', '세상이 움직이는 방식을 보면, 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다, 그리고 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.', '오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.'),
    (2327, 'kor', 'long', '다시 시작하고 싶은 날에, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다, 그리고 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.', '오래 걷던 산책길 끝에서 이름 모를 꽃 한 송이가 바람에 흔들리고 있었다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 오래된 꿈은 잊힌 것이 아니라 다시 꺼낼 알맞은 순간을 기다리고 있을지 모른다. 그래서 오늘만큼은 서두르지 않고 내 마음의 속도에 맞추어 걷기로 했다.'),
    (2328, 'kor', 'long', '구름이 걷힌 순간 빈 의자 옆의 온기는 무거운 마음을 한결 가볍게 만든다. 집으로 돌아오는 길에 화분 끝의 새잎은 혼자였던 시간을 포근하게 채워 준다. 비가 그친 뒤 거리의 느린 그림자는 무거운 마음을 한결 가볍게 만든다.', '기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.'),
    (2329, 'kor', 'long', '마지막 불빛만 남았을 때, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 동시에 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    (2330, 'kor', 'long', '냉장고 앞에 멈춰 서면, 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다. 동시에 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.', '반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.'),
    (2331, 'kor', 'long', '누군가의 도움이 필요할 때, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다, 그리고 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.'),
    (2332, 'kor', 'long', '누군가의 도움이 필요할 때, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.', '누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    (2333, 'kor', 'long', '하루를 마무리하기 전에, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다, 그리고 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.', '기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    (2334, 'kor', 'long', '미안한 마음을 전해야 한다면, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다, 그리고 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.', '배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.'),
    (2335, 'kor', 'long', '익숙한 현상을 다시 바라보면, 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다, 그리고 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.', '진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.'),
    (2336, 'kor', 'long', '마감이 가까워질수록, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 동시에 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.', '늦은 밤 책장을 덮자 방 안에는 시계 소리와 잔잔한 음악만 남았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 모든 관계에는 말보다 침묵으로 서로를 이해해야 하는 순간이 찾아온다. 오늘의 작은 위로가 내일을 시작할 힘이 되어 줄 것이라고 믿어 보기로 했다.'),
    (2337, 'kor', 'long', '차를 한 잔 마시며 골목에서 만난 바람은 복잡했던 생각을 잠시 쉬게 한다. 잠에서 막 깨어나 물 위에 번진 달빛은 오늘을 천천히 바라보게 만든다. 회의가 끝난 뒤 정류장의 잔잔한 음악은 지친 마음에 작은 온기를 남긴다.', '잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.'),
    (2338, 'kor', 'long', '마지막 불빛만 남았을 때, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어. 동시에 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.', '집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.'),
    (2339, 'kor', 'long', '운동을 새로 결심하면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다, 그리고 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.', '집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.'),
    (2340, 'kor', 'long', '잠깐 숨을 고르며, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다, 그리고 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    (2341, 'kor', 'long', '시간이 부족하게 느껴지면, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다. 동시에 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.'),
    (2342, 'kor', 'long', '마감이 가까워질수록, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다, 그리고 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.'),
    (2343, 'kor', 'long', '오랜 친구를 다시 만났을 때, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 동시에 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.', '익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.'),
    (2344, 'kor', 'long', '오랜 연구의 결과를 살펴보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 동시에 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.', '좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.'),
    (2345, 'kor', 'long', '평소와 다른 길을 걷다가, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.', '첫눈이 내린 거리는 익숙한 풍경을 새하얀 장면으로 천천히 바꾸어 놓았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 기다림은 답이 없는 시간이 아니라 마음이 스스로를 정리하는 과정일 수 있다. 작은 변화라도 믿어 보기로 하자 마음 한편에 가벼운 설렘이 피어났다.'),
    (2346, 'kor', 'long', '음악이 끝난 뒤 길모퉁이의 작은 꽃은 멀어진 마음을 다시 돌아보게 한다. 낯선 동네를 지나다가 멀리 켜진 불빛은 잊고 있던 마음을 조용히 깨운다. 새벽에 깨어난 도시는 지나간 계절의 기억을 데려온다.', '아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.'),
    (2347, 'kor', 'long', '서로의 손을 놓치기 전에, 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼. 동시에 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.'),
    (2348, 'kor', 'long', '비밀번호를 막 바꾸고 나면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다, 그리고 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.', '좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.'),
    (2349, 'kor', 'long', '작은 성공을 만났을 때, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다.', '청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.'),
    (2350, 'kor', 'long', '시간이 부족하게 느껴지면, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다, 그리고 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.', '세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져.'),
    (2351, 'kor', 'long', '평소와 다른 길을 걷다가, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자. 동시에 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.', '깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.'),
    (2352, 'kor', 'long', '대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다. 고마움을 표현하고 싶을 때, 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.'),
    (2353, 'kor', 'long', '세상이 움직이는 방식을 보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 동시에 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.'),
    (2354, 'kor', 'long', '혼자 결정하기 어렵다면, 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다, 그리고 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '바닷가에 앉아 밀려왔다 멀어지는 파도의 리듬을 오래 바라보았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 행복은 대단한 장면보다 좋아하는 사람과 나눈 짧은 웃음 속에 자주 숨어 있다. 어둠이 깊어질수록 작은 불빛 하나가 더 선명해진다는 사실을 기억했다.'),
    (2355, 'kor', 'long', '책장을 천천히 넘기다가 화분 끝의 새잎은 오늘을 천천히 바라보게 만든다. 구름 사이로 나온 달빛은 지금 이 순간에 마음을 머물게 한다. 골목을 스치는 저녁 바람은 멀어진 마음을 다시 돌아보게 한다.', '스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다.'),
    (2356, 'kor', 'long', '마지막 불빛만 남았을 때, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.'),
    (2357, 'kor', 'long', '비밀번호를 막 바꾸고 나면, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다, 그리고 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.', '어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.'),
    (2358, 'kor', 'long', '계획이 어긋난 날에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다.'),
    (2359, 'kor', 'long', '실수가 마음에 남는다면, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야.'),
    (2360, 'kor', 'long', '새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 누군가의 도움이 필요할 때, 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.'),
    (2361, 'kor', 'long', '미안한 마음을 전해야 한다면, 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다, 그리고 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.'),
    (2362, 'kor', 'long', '과학의 시선으로 세상을 보면, 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다, 그리고 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다.'),
    (2363, 'kor', 'long', '실수가 마음에 남는다면, 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다. 동시에 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '따뜻한 차를 우려 놓고 창밖의 빗방울이 흘러내리는 모습을 지켜보았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 조금 늦어도 괜찮다는 믿음은 멈추지 않고 나아갈 수 있는 여유를 만들어 준다. 내일도 완벽하지 않겠지만 오늘보다 조금 다정한 사람이 되고 싶어졌다.'),
    (2364, 'kor', 'long', '해가 기울 무렵 문틈으로 든 바람은 서두르던 걸음을 잠시 멈추게 한다. 구름이 걷힌 순간 정류장의 잔잔한 음악은 지나온 시간을 따뜻하게 이해하게 한다. 구름이 걷힌 순간 빈 의자 옆의 온기는 마음 한쪽에 잔잔한 여운을 남긴다.', '완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.'),
    (2365, 'kor', 'long', '모두가 포기하라고 말해도, 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야. 동시에 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.', '해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.'),
    (2366, 'kor', 'long', '잃어버린 물건을 찾다 보면, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다, 그리고 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    (2367, 'kor', 'long', '조용한 주말 저녁에, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.'),
    (2368, 'kor', 'long', '어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 다시 시작하고 싶은 날에, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.'),
    (2369, 'kor', 'long', '예상 밖의 문제가 생기면, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자, 그리고 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다.'),
    (2370, 'kor', 'long', '마음이 서로 엇갈린 순간에는, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다, 그리고 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.', '모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    (2371, 'kor', 'long', '세상이 움직이는 방식을 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.'),
    (2372, 'kor', 'long', '익숙한 방법이 막히면, 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '서랍을 정리하다 발견한 사진 속에서 오래전의 내가 환하게 웃고 있었다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 가까운 사람일수록 익숙함 뒤에 숨은 고마움을 자주 표현해야 한다. 그날 이후 나는 평범한 순간을 예전보다 조금 더 오래 바라보게 되었다.'),
    (2373, 'kor', 'long', '집으로 돌아오는 길에 하늘에 남은 노을은 마음 깊은 곳에 맑은 숨을 불어넣는다. 한참을 기다리다가 멀리 켜진 불빛은 말하지 못한 감정을 가만히 안아 준다. 음악이 끝난 뒤 빈 의자 옆의 온기는 사소한 행복이 가까이 있음을 알려 준다.', '속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.'),
    (2374, 'kor', 'long', '도망칠 기회가 생겼을 때, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야, 그리고 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.'),
    (2375, 'kor', 'long', '일찍 자겠다고 다짐한 밤에는, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다, 그리고 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.', '업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.'),
    (2376, 'kor', 'long', '익숙한 방법이 막히면, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다, 그리고 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.'),
    (2377, 'kor', 'long', '예상 밖의 문제가 생기면, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.', '오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.'),
    (2378, 'kor', 'long', '누군가의 도움이 필요할 때, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.'),
    (2379, 'kor', 'long', '좋아하는 사람을 바라볼 때, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다, 그리고 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.', '한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.'),
    (2380, 'kor', 'long', '깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다. 작은 단서에서 질문을 시작하면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.', '상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.'),
    (2381, 'kor', 'long', '익숙한 방법이 막히면, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다, 그리고 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.', '새벽 공기가 차가워 창문을 닫으려다 희미하게 밝아 오는 하늘을 보았다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 마음이 복잡할수록 답을 서두르기보다 지금의 감정을 온전히 바라볼 필요가 있다. 한참을 머물다 일어서는 발걸음은 이상할 만큼 가볍고 단단해져 있었다.'),
    (2382, 'kor', 'long', '새로운 길을 걷다가 빈 의자 옆의 온기는 바쁜 하루에 느린 숨을 선물한다. 비가 그친 뒤 유리창의 빗방울은 평범한 하루를 조금 특별하게 만든다. 차를 한 잔 마시며 우편함 속 편지는 복잡했던 생각을 잠시 쉬게 한다.', '실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다.'),
    (2383, 'kor', 'long', '도망칠 기회가 생겼을 때, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어, 그리고 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.'),
    (2384, 'kor', 'long', '청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다. 잃어버린 물건을 찾다 보면, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다.', '막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다.'),
    (2385, 'kor', 'long', '다시 시작하고 싶은 날에, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.', '한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.'),
    (2386, 'kor', 'long', '비가 그친 오후에, 기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 동시에 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    (2387, 'kor', 'long', '다시 시작하고 싶은 날에, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자, 그리고 십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다.', '나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다. 서로 다른 자연 현상을 함께 살펴보면 세상을 이해하는 질문도 넓어진다. 기억은 꺼내 볼 때마다 그대로 재생되지 않고 조금씩 다시 만들어진다.'),
    (2388, 'kor', 'long', '의견이 쉽게 좁혀지지 않으면, 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다. 동시에 상대의 하루를 묻고 대답을 기다리는 일도 충분히 깊은 배려다.', '어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다. 배움은 많은 내용을 한꺼번에 담는 일보다 이해의 빈틈을 찾아 메우는 과정에 가깝다. 배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다.'),
    (2389, 'kor', 'long', '보이지 않는 원리를 생각하면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다, 그리고 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.', '미안하다는 말에는 변명보다 다음에 달라질 행동이 함께 있어야 한다. 관계는 큰 약속보다 자주 건네는 관심과 정확히 듣는 태도로 유지된다. 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.'),
    (2390, 'kor', 'long', '답을 찾기 어려운 순간에, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다.', '낙엽이 수북한 길을 걸을 때마다 발끝에서 바스락거리는 소리가 났다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 좋았던 기억은 붙잡을 때보다 편안히 놓아줄 때 더 따뜻한 모습으로 남는다. 아직 오지 않은 날들을 걱정하기보다 지금 곁에 있는 온기를 믿기로 했다.'),
    (2391, 'kor', 'long', '다정하게 건넨 인사는 바쁜 하루에 느린 숨을 선물한다. 새로운 길을 걷다가 길모퉁이의 작은 꽃은 지친 마음에 작은 온기를 남긴다. 오랜 약속을 마치고 문틈으로 든 바람은 지친 마음에 작은 온기를 남긴다.', '두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자. 목표를 향해 가는 동안에는 속도보다 방향을 지키는 힘이 중요하다. 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    (2392, 'kor', 'long', '모두가 포기하라고 말해도, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까, 그리고 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.', '문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다. 좋은 생활 방식은 의지보다 다시 반복할 수 있는 구조에 가깝다. 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.'),
    (2393, 'kor', 'long', '정리를 시작하고 나면, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다, 그리고 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.', '동료에게 일찍 알린 작은 문제는 늦게 발견한 큰 문제가 되지 않는다. 업무의 속도는 서두르는 데서가 아니라 기준과 다음 행동을 분명히 하는 데서 나온다. 집중할 시간과 답장할 시간을 나누면 둘 다 더 선명해진다.'),
    (2394, 'kor', 'long', '하루를 마무리하기 전에, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다, 그리고 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.', '정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다. 사람의 결심은 단단하지만 알람과 냉장고와 간식도 만만한 상대는 아니다. 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.'),
    (2395, 'kor', 'long', '잠깐 숨을 고르며, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다, 그리고 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야. 이야기의 끝처럼 보이는 순간에도 인물에게는 다음 선택이 남아 있다. 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.'),
    (2396, 'kor', 'long', '혼자 결정하기 어렵다면, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자. 동시에 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자.', '번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 익숙한 풍경 속에도 자세히 들여다봐야 알 수 있는 과학의 원리가 숨어 있다. 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.'),
    (2397, 'kor', 'long', '서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다. 오랜 친구를 다시 만났을 때, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.', '틀린 답을 기록하면 다음에 같은 생각의 길로 빠지는 일을 줄일 수 있다. 새로운 지식은 읽는 데서 끝나지 않고 설명하고 떠올릴 때 자기 것이 된다. 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    (2398, 'kor', 'long', '익숙한 현상을 다시 바라보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다, 그리고 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다. 가까운 사이일수록 고마움과 서운함을 늦지 않게 표현하는 일이 중요하다. 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.'),
    (2399, 'kor', 'long', '예상 밖의 문제가 생기면, 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다, 그리고 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '오랜만에 찾은 동네에는 달라진 간판과 그대로인 골목이 나란히 있었다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 오늘의 작은 선택이 당장은 보이지 않아도 내일의 분위기를 바꾸어 놓는다. 익숙한 하루 안에도 아직 발견하지 못한 아름다움이 많다는 것을 알게 되었다.'),
    (2400, 'kor', 'long', '불을 낮춘 다음 우편함 속 편지는 마음 한쪽에 잔잔한 여운을 남긴다. 해가 기울 무렵 빈 의자 옆의 온기는 평범한 하루를 조금 특별하게 만든다. 구름이 걷힌 순간 정류장의 잔잔한 음악은 멀어진 마음을 다시 돌아보게 한다.', '어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다. 뜻대로 되지 않는 날에도 다시 움직일 이유는 남아 있다. 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.'),
    (2401, 'kor', 'long', '중요한 선택을 앞두고, 정답은 없어도 선택은 해야 해 그리고 나는 우리를 선택할 거야. 동시에 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.', '십 분 안에 끝낼 수 있는 일은 미루지 않는 편이 마음도 가볍다. 마음의 부담을 줄이려면 막연한 걱정을 구체적인 행동으로 바꾸어야 한다. 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    (2402, 'kor', 'long', '냉장고 앞에 멈춰 서면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다, 그리고 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.', '완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다. 문제가 커지기 전에 작은 이상을 알리는 문화가 팀을 더 안전하게 만든다. 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    (2403, 'kor', 'long', '혼자 결정하기 어렵다면, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다. 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.', '운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다. 생활 속 작은 실수는 지나고 보면 가장 오래 이야기되는 장면이 되곤 한다. 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.'),
    (2404, 'kor', 'long', '예상 밖의 문제가 생기면, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다. 동시에 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어. 두려움이 가장 커진 장면에서 한 걸음 내딛는 선택이 흐름을 바꾸기도 한다. 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.'),
    (2405, 'kor', 'long', '작은 성공을 만났을 때, 새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 동시에 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.', '사막의 밤이 추운 이유는 열을 붙잡아 둘 수분이 적기 때문이다. 자연은 눈에 보이는 모습보다 훨씬 복잡한 연결을 통해 움직인다. 깊은 바다의 생물은 스스로 빛을 만들어 신호를 보내기도 한다.'),
    (2406, 'kor', 'long', '고마움을 표현하고 싶을 때, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다, 그리고 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.', '새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 모르는 부분을 정확히 발견하면 공부의 다음 순서도 자연스럽게 보인다. 잘 읽는 사람은 중요한 문장뿐 아니라 이해되지 않는 부분도 표시한다.'),
    (2407, 'kor', 'long', '익숙한 현상을 다시 바라보면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다. 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.', '힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 서로를 이해한다는 것은 같은 생각을 갖는 일보다 다른 마음을 끝까지 듣는 일에 가깝다. 대화의 온도는 무슨 말을 했는지보다 어떻게 들었는지에 남는다.'),
    (2408, 'kor', 'long', '익숙한 방법이 막히면, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다, 그리고 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.', '작은 화분 끝에 돋아난 새잎이 아침 햇빛을 받아 투명하게 빛나고 있었다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 우리는 큰 사건보다 사소한 장면 하나를 더 오래 기억하며 살아가기도 한다. 나는 충분히 쉬어 가는 일도 앞으로 나아가는 방법임을 받아들이기로 했다.'),
    (2409, 'kor', 'long', '불을 낮춘 다음 물 위에 번진 달빛은 서두르던 걸음을 잠시 멈추게 한다. 비가 그친 뒤 정류장의 잔잔한 음악은 사소한 행복이 가까이 있음을 알려 준다. 불을 낮춘 다음 창가에서 본 햇살은 바쁜 하루에 느린 숨을 선물한다.', '목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자. 성장은 눈에 띄는 순간보다 포기하지 않은 시간 속에서 쌓인다. 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.'),
    (2410, 'kor', 'long', '도시가 갑자기 조용해지면, 지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아, 그리고 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.', '대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자. 사소한 정리 습관 하나가 하루 전체의 흐름을 예상보다 크게 바꾸기도 한다. 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    (2411, 'kor', 'long', '잠이 덜 깬 아침에는, 한 주의 첫날은 잘못이 없지만 사람들은 대체로 그날을 의심한다. 동시에 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.', '자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다. 좋은 협업은 각자의 역할과 완료 조건을 같은 언어로 이해하는 데서 시작된다. 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.'),
    (2412, 'kor', 'long', '배운 내용을 하루 뒤에 다시 떠올리면 기억의 연결이 단단해진다. 익숙한 방법이 막히면, 어려운 개념은 다른 사람에게 설명해 보면 빈틈이 분명하게 보인다.', '회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다. 부지런해지려던 계획이 엉뚱한 방향으로 자라는 날도 가끔은 필요하다. 일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.'),
    (2413, 'kor', 'long', '예상 밖의 문제가 생기면, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자, 그리고 어제보다 나아진 한 가지를 찾으면 오늘은 충분히 의미가 있다.', '마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까. 모든 길이 사라진 듯한 밤에도 작은 불빛 하나는 방향이 되어 준다. 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    (2414, 'kor', 'long', '평소와 다른 길을 걷다가, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자, 그리고 문제가 복잡할수록 사실과 추측을 먼저 나누어 보는 것이 좋다.', '달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다. 작은 생물의 행동과 먼 우주의 변화는 모두 관찰에서 시작된 질문에 답한다. 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    (2415, 'kor', 'long', '서운한 마음이 생겼다면, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다. 오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다.', '질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다. 꾸준한 복습과 솔직한 질문은 재능보다 오래 믿을 수 있는 학습 도구다. 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.'),
    (2416, 'kor', 'long', '과학의 시선으로 세상을 보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다. 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.', '오래된 우정은 자주 만나지 못해도 다시 이어지는 길을 기억한다. 진심은 화려한 말보다 약속을 지키고 곁을 내어 주는 행동에서 잘 드러난다. 서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.'),
    (2417, 'kor', 'long', '마감이 가까워질수록, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다. 동시에 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.', '저녁 식사를 마친 뒤 불을 낮추니 집 안의 시간이 조금 느리게 흐르는 듯했다. 조용한 장면을 오래 바라보면 지나치던 감정이 비로소 모습을 드러낸다. 평범한 하루를 견디게 하는 힘은 멀리 있는 목표보다 가까운 애정에서 온다. 말로 설명하기 어려운 감정은 그대로 두어도 충분히 아름다울 수 있었다.'),
    (2418, 'kor', 'long', '책장을 천천히 넘기다가 물 위에 번진 달빛은 조용한 설렘을 마음속에 피워 낸다. 회의가 끝난 뒤 멀리 켜진 불빛은 멀어진 마음을 다시 돌아보게 한다. 집으로 돌아오는 길에 정류장의 잔잔한 음악은 멀어진 마음을 다시 돌아보게 한다.', '기회는 준비된 순간보다 움직이기 시작한 순간에 더 자주 보인다. 변화는 거창한 결심보다 반복할 수 있는 행동에서 시작된다. 완벽한 준비보다 오늘 시작한 작은 행동이 더 멀리 간다.'),
    (2419, 'kor', 'long', '도시가 갑자기 조용해지면, 오늘 도망치면 장면은 멈추지만 다시 걸으면 이야기가 이어져, 그리고 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.', '새로운 습관은 거창한 계획보다 반복할 수 있는 크기로 시작하자. 복잡한 하루는 해야 할 일을 작고 분명하게 나눌 때 정리되기 시작한다. 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.'),
    (2420, 'kor', 'long', '일찍 자겠다고 다짐한 밤에는, 냉장고 문을 열고 목적을 잊었다면 잠깐의 모험은 성공한 셈이다. 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.', '반복되는 실수는 사람보다 과정에서 원인을 찾을 때 더 잘 고쳐진다. 함께 일할수록 결과만큼 과정과 판단을 투명하게 공유하는 태도가 중요하다. 좋은 회의는 말이 많은 회의가 아니라 다음 행동이 분명한 회의다.'),
    (2421, 'kor', 'long', '누군가의 도움이 필요할 때, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다. 실력을 비교할 대상은 타인보다 어제의 나인 편이 오래 도움이 된다.', '간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다. 평범한 하루에는 계획대로 되지 않아서 오히려 웃게 되는 순간이 많다. 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    (2422, 'kor', 'long', '조용한 주말 저녁에, 실패한 횟수보다 다시 시도한 횟수가 사람을 더 정확히 설명한다, 그리고 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.', '누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해. 막다른 상황에 닿을수록 무엇을 지키고 싶은지는 오히려 선명해진다. 문이 닫혔다고 끝난 것은 아니야 우리는 다른 길을 찾으면 돼.'),
    (3043, 'eng', 'short', 'When the familiar method fails, start a new habit at a size that can survive a difficult day.', 'A friendly smile awakens a quiet sense of gratitude.'),
    (3045, 'eng', 'short', 'When gratitude needs a voice, sharing a small disappointment early can protect a relationship from larger distance.', 'The color of autumn trees helps the heart release what it no longer needs.'),
    (3047, 'eng', 'short', 'Before beginning unfamiliar work, a precise question can solve a blocked task faster than silent effort.', 'A calm night sky becomes a gentle promise for the days ahead.'),
    (3049, 'eng', 'short', 'Before an important choice, letting go would be easier, but I did not come here for an easy ending.', 'The promise of spring reveals beauty in the most ordinary places.'),
    (3051, 'eng', 'short', 'When a snack becomes strangely persuasive, opening the refrigerator without a plan still counts as a short expedition.', 'A cool breeze at dawn brings a little warmth to a tired heart.'),
    (3052, 'eng', 'short', 'When help becomes necessary, a different point of view can reopen a problem when the familiar method fails.', 'The memory of laughter makes an ordinary day feel quietly special.'),
    (3053, 'eng', 'short', 'On the slow journey home, a small action today can travel farther than a perfect plan tomorrow.', 'A path covered in leaves returns a forgotten memory with gentle clarity.'),
    (3054, 'eng', 'short', 'As a deadline moves closer, a useful record includes both the result and the reason behind it.', 'The last note of the melody gives crowded thoughts a place to rest.'),
    (3056, 'eng', 'short', 'When two people misunderstand each other, a real apology includes a different action instead of a longer explanation.', 'A bright kitchen window turns a brief pause into a lasting memory.'),
    (3057, 'eng', 'short', 'When change is watched carefully, a large cloud can contain an enormous amount of water despite its gentle shape.', 'The scent of wet earth reminds us that comfort can be simple.'),
    (3058, 'eng', 'short', 'Before bringing the day to a close, priority should follow real impact rather than the loudest request.', 'A peaceful train ride leaves a soft trace long after it fades.'),
    (3060, 'eng', 'short', 'When escape becomes possible, when the whole city became quiet, your voice was the one sound I could find.', 'The light across the river makes the familiar world feel new again.'),
    (3062, 'eng', 'short', 'After ambitious cleaning begins, long meetings quietly teach everyone how to check the clock without moving.', 'The sound of summer rain gives crowded thoughts a place to rest.'),
    (3064, 'eng', 'short', 'While taking a brief pause, being a beginner means there is still plenty of room to grow.', 'A familiar song turns a brief pause into a lasting memory.'),
    (3065, 'eng', 'short', 'When a choice feels difficult, when the list feels endless, complete the smallest useful task first.', 'The quiet evening breeze reminds us that comfort can be simple.'),
    (3067, 'eng', 'short', 'When disappointment begins to grow, gratitude should be spoken aloud even in the relationships that feel most familiar.', 'The first winter snow makes the familiar world feel new again.'),
    (3068, 'eng', 'short', 'When science offers another view, an octopus has three hearts, and two of them move blood through the gills.', 'Warm light by the window invites the heart to move at a kinder pace.'),
    (3069, 'eng', 'short', 'On a quiet Monday morning, share the conclusion, the evidence, and the next step in the same note.', 'The scent of fresh coffee carries hope into the quieter parts of the day.'),
